local config = {
  ui_story_5010_50100101_1_dialog_content = "\"Como seres vivos, debemos mostrar amor, compasión y respeto a todas las vidas\".",
  ui_story_5010_50100101_2_dialog_content = "\"Como tal, hicimos lo que pensamos que era correcto, y no es necesario agradecernos\".",
  ui_story_5010_50100101_3_dialog_content = "\"Pórtate bien, joven PlayerName.\"",
  ui_story_5010_50100101_4_dialog_content = "Guau... La carta del <color=#FFB400>gremio lin</color> ¡realmente demuestra que son una familia muy civilizada!",
  ui_story_5010_50100101_5_dialog_content = "Debería intentar escribir una carta a Vice usando el mismo estilo algún día...",
  ui_story_5010_50100101_6_dialog_content = "\"Querido Vice, ¿cómo te ha ido últimamente? ¿Te has acostumbrado a tu régimen de entrenamiento en Illumina?\"",
  ui_story_5010_50100101_7_dialog_content = "\"Independientemente, como camaradas, aprender el sutil arte de cocinar es de suma importancia...\"",
  ui_story_5010_50100101_8_dialog_content = "\"¡Pájaro gordito! ¡Gordito!\"",
  ui_story_5010_50100101_9_dialog_content = "¡Oye! ¡Brusco!",
  ui_story_5010_50100101_10_dialog_content = "¿Ah?",
  ui_story_5010_50100101_11_dialog_content = "¡Yaaaas!",
  ui_story_5010_50100101_12_dialog_content = "¿Quieres escuchar mi chiste primero?",
  ui_story_5010_50100101_13_dialog_content = "¡Es super-duper-extra divertido! ¡Yoshi perdió dos libras solo por reírse después de escucharlo!",
  ui_story_5010_50100101_14_dialog_content = "En otro momento, tal vez... Oye, tienes una carta colgando de tu bolso ahí.",
  ui_story_5010_50100101_15_dialog_content = "Parece que está dirigido a... ¿a mí? Aquí, déjame verlo.",
  ui_story_5010_50100101_16_dialog_content = "¿Ni siquiera tienes tiempo para una pequeña broma? ¡Bien!",
  ui_story_5010_50100101_17_dialog_content = "Aquí está tu carta!",
  ui_story_5010_50100101_18_dialog_content = "Desde el <color=#FFB400>Señor de la sombra</color> ¡él mismo!",
  ui_story_5010_50100101_19_dialog_content = "Me pidieron específicamente que te viera leer todo.",
  ui_story_5010_50100101_20_dialog_content = "¡Así que date prisa! ¡No tengo todo el día!",
  ui_story_5010_50100101_21_dialog_content = "¡O-bien! Me pregunto que podría ser? Debe ser bastante importante...",
  ui_story_5010_50100101_22_dialog_content = "Estimado PlayerName,",
  ui_story_5010_50100101_24_dialog_content = "\"Basado en tus diversas obras...\"",
  ui_story_5010_50100101_25_dialog_content = "\"Tanto la Federación Illumina como Lumopolis te reconocen como el único representante de los caelestitas. Naturalmente, Umbraton no es una excepción...\"",
  ui_story_5010_50100101_26_dialog_content = "¡Vamos, ya! Tengo otras cartas que entregar, ¿sabes?",
  ui_story_5010_50100101_27_dialog_content = "\"Como representante de Umbraton, ahora declaro que todos los bienes de Caelestite depositados en Umbraton son propiedad exclusiva de usted, el último de los Caelestite...\"",
  ui_story_5010_50100101_28_dialog_content = "\"Puede usar esta carta como prueba de su derecho a reclamar la propiedad, y la sede del gremio de Umbraton se encargará de todos los procedimientos logísticos...\"",
  ui_story_5010_50100101_29_dialog_content = "\"La ubicación de la sede es... La persona a cargo de este asunto es... La información de contacto de su terminal es la siguiente...\"",
  ui_story_5010_50100101_30_dialog_content = "\"... Y <color=#FFB400>Templo no conformista</color> será responsable de acompañarlo al banco del Gremio, así como de arreglar todo el papeleo de la herencia...\"",
  ui_story_5010_50100101_31_dialog_content = "Diecisiete luciérnagas... dieciocho luciérnagas...",
  ui_story_5010_50100101_32_dialog_content = "Atentamente, Istvan.",
  ui_story_5010_50100101_33_dialog_content = "¿Activos de Caelestita...?",
  ui_story_5010_50100101_34_dialog_content = "Eh... ¿eh? ¿Qué tipo de activos tenían los Caelestites en Umbraton?",
  ui_story_5010_50100101_35_dialog_content = "Ni idea.",
  ui_story_5010_50100101_36_dialog_content = "Entonces, ¿sabe cuánto tiempo le toma al Gremio manejar todo el papeleo?",
  ui_story_5010_50100101_37_dialog_content = "¡Ni idea!",
  ui_story_5010_50100101_38_dialog_content = "Entonces... ¿Al menos sabes quién es? <color=#FFB400>Templo no conformista</color> persona es?",
  ui_story_5010_50100101_39_dialog_content = "¡Ajá! ¡Conozco esta!",
  ui_story_5010_50100101_40_dialog_content = "¡Está a cargo de la sede del Gremio y es la hija adoptiva del Señor de las Sombras!",
  ui_story_5010_50100101_41_dialog_content = "Escuché que regresó a Umbraton después de estudiar en Lumopolis, ¡y tiene algunos lindos cachorros con ella!",
  ui_story_5010_50100101_42_dialog_content = "¿Hija adoptiva? ¿Cuántas hijas adoptivas tiene el Señor de las Sombras...?",
  ui_story_5010_50100101_43_dialog_content = "¡Meh, eso no es importante!",
  ui_story_5010_50100101_44_dialog_content = "¡Oh sí! Señora <color=#FFB400>Naroxel</color> ¡También me pidió que le pasara un mensaje!",
  ui_story_5010_50100101_45_dialog_content = "¿Por qué no me lo dice ella misma...?",
  ui_story_5010_50100101_46_dialog_content = "Ella está muy ocupada, ¿sabes? Ahora escucha...",
  ui_story_5010_50100101_47_dialog_content = "\"Saludos, PlayerName.\"",
  ui_story_5010_50100101_48_dialog_content = "\"Me ha llamado la atención que cierto conjunto de <color=#FFB400>componentes de la sala de simulación</color> pronto aparecerá en una subasta clandestina en Umbraton\".",
  ui_story_5010_50100101_49_dialog_content = "\"Según tengo entendido, componentes como estos se usaban a menudo para modificar o incluso actualizar Colossi\".",
  ui_story_5010_50100101_50_dialog_content = "\"Si está interesado, puede que le convenga verlos por sí mismo. ¿Quizás puedan ser útiles para Soroz en el futuro?\"",
  ui_story_5010_50100101_51_dialog_content = "\"Que la naturaleza te proteja siempre... Tu amigo, Naroxel\".",
  ui_story_5010_50100101_52_dialog_content = "\"<color=#FFB400>Componentes de la sala de simulación</color>\"?... ¿Oye, Eho?",
  ui_story_5010_50100101_53_dialog_content = "¿Graznar? ¿Ahora que?",
  ui_story_5010_50100101_54_dialog_content = "¿Sabes de qué se trata la subasta clandestina?",
  ui_story_5010_50100101_55_dialog_content = "Bueno, ¡por supuesto que sí! Es una subasta, obviamente... ¡Y sucede que es clandestina!",
  ui_story_5010_50100101_56_dialog_content = "Lo sabrías si vas y lo ves por ti mismo, ¿verdad? Ah, eres muy lento.",
  ui_story_5010_50100101_57_dialog_content = "¡Me voy de verdad, ahora! ¡Todavía tengo otras dieciocho entregas para hacer hoy!",
  ui_story_5010_50100101_58_dialog_content = "Está bien, gracias por... Oh, ella ya se fue. Debe ser lindo tener alas así...",
  ui_story_5010_50100101_59_dialog_content = "Hmm... mucho en lo que pensar ahora. necesito algo de tiempo...",
  ui_story_5010_50100101_60_dialog_content = "La sede del gremio, la subasta clandestina...",
  ui_story_5010_50100101_61_dialog_content = "¡Vaya! ¡También puedo pasar por Lin Guild y saludarlos!",
  ui_story_5010_50100101_62_dialog_content = "\"Por favor, póngase en contacto con el siguiente número a través de la terminal, y el líder del Gremio se reunirá con usted en las afueras de Umbraton...\"",
  ui_story_5010_50100101_63_dialog_content = "Parece que nuestra próxima parada es <color=#FFB400>Umbratón</color>!",
  ui_story_5010_50100201_1_dialog_content = "¿Hola? Es esto PlayerName? Este es Bethel, del Gremio Umbraton.",
  ui_story_5010_50100201_2_dialog_content = "H-hola!",
  ui_story_5010_50100201_3_dialog_content = "Por favor, aterrice al este de la <color=#FFB400>Presa de cicatrices</color>. Te esperaré allí.",
  ui_story_5010_50100201_4_dialog_content = "¡No es problema!",
  ui_story_5010_50100201_5_dialog_content = "Umbraton se ve realmente impresionante desde este ángulo.",
  ui_story_5010_50100201_6_dialog_content = "Umbraton... Una ciudad conocida como la Sombra de Lumopolis.",
  ui_story_5010_50100201_7_dialog_content = "<color=#e8d9bb>Pronto estaremos llegando a nuestro destino. Confirme su zona de aterrizaje antes de la llegada.</color>",
  ui_story_5010_50100201_8_dialog_content = "Oh, no... Olvidé por completo preguntar dónde está la Presa de las Cicatrices.",
  ui_story_5010_50100201_9_dialog_content = "Supongo que iré a buscarlo yo mismo...",
  ui_story_5010_50100201_10_dialog_content = "Hola de nuevo. Usted debe ser PlayerName. soy betel",
  ui_story_5010_50100201_11_dialog_content = "¡Sí! H-Hola...",
  ui_story_5010_50100201_12_dialog_content = "Y este debe ser el Coloso... Es tan magnífico como dicen las historias. Me imagino que debe ser bastante dificil de pilotar?",
  ui_story_5010_50100201_13_dialog_content = "Parece que tuviste algunas dificultades para aterrizarlo.",
  ui_story_5010_50100201_14_dialog_content = "N-No realmente, solo me perdí un poco. No vengo a Umbraton muy a menudo, verá...",
  ui_story_5010_50100201_15_dialog_content = "Para ser honesto, casi me pierdo en mi camino hacia aquí también.",
  ui_story_5010_50100201_16_dialog_content = "Seguro que Umbraton ha cambiado mucho en los últimos años...",
  ui_story_5010_50100201_17_dialog_content = "Pero basta de eso. Por favor, por aquí.",
  ui_story_5010_50100201_18_dialog_content = "(Si hubiera sabido que iba a ser tan formal, me habría arreglado un poco...)",
  ui_story_5010_50100201_19_dialog_content = "Entonces... ¿vamos a la sede ahora?",
  ui_story_5010_50100201_20_dialog_content = "Además... ¿Podría decirme cuáles son exactamente estos activos de Caelestite?",
  ui_story_5010_50100201_21_dialog_content = "El libro mayor los describe como varios cofres. Sólo el propietario está autorizado para abrirlos y conocer su contenido.",
  ui_story_5010_50100201_22_dialog_content = "El cuartel general del gremio de Umbraton... Disculpe, pero ¿maneja todas las operaciones del gremio? ¿Las subastas clandestinas también están bajo su jurisdicción?",
  ui_story_5010_50100201_23_dialog_content = "¿Subastas clandestinas?",
  ui_story_5010_50100201_24_dialog_content = "Aunque no tengo idea de dónde encontraste este término, me temo que tengo muy poca información para divulgar al respecto.",
  ui_story_5010_50100201_25_dialog_content = "¿Podría ser que desee subastar los activos de Caelestite que ha venido a reclamar?",
  ui_story_5010_50100201_26_dialog_content = "¡Ay! ¡N-no quise decir eso! Acabo de enterarme de que alguien iba a subastar algunas cosas de Caelestite... Así que pensé en preguntarte al respecto.",
  ui_story_5010_50100201_27_dialog_content = "Eso estaría muy por debajo de nosotros. El Gremio Umbraton nunca participaría en la venta no autorizada de las propiedades de otras personas.",
  ui_story_5010_50100201_28_dialog_content = "C-Correcto.",
  ui_story_5010_50100201_29_dialog_content = "Por favor, sigue así, si quieres.",
  ui_story_5010_50100201_30_dialog_content = "...",
  ui_story_5010_50100201_31_dialog_content = "(Siento que necesito decir algo aquí... ¿Pero de qué debería hablar?)",
  ui_story_5010_50100201_32_option_content = "Pregunta por el gremio Lin",
  ui_story_5010_50100201_33_dialog_content = "¿Betel...? ¿Estás familiarizado con el <color=#FFB400>gremio lin</color>?",
  ui_story_5010_50100201_34_dialog_content = "Por supuesto.",
  ui_story_5010_50100201_35_option_content = "Pregunta por la represa",
  ui_story_5010_50100201_36_dialog_content = "¡Esa presa que pasamos de camino aquí era enorme! ¿La gente de Umbraton lo construyó ellos mismos?",
  ui_story_5010_50100201_37_dialog_content = "Fue construido a instancias del Señor de las Sombras para eludir cualquier anomalía climática peligrosa.",
  ui_story_5010_50100201_38_dialog_content = "Bajo su dirección, cada uno de los principales gremios invirtió en el proyecto, siendo el mayor benefactor el <color=#FFB400>Familia Lin</color>.",
  ui_story_5010_50100201_39_dialog_content = "Entonces... El gremio Lin...",
  ui_story_5010_50100201_40_dialog_content = "¿Sí? ¿Estás interesado en ellos?",
  ui_story_5010_50100201_41_dialog_content = "Solo he escuchado algunas cosas aquí y allá sobre ellos. Después de todo, siempre han sido bastante... escurridizos.",
  ui_story_5010_50100201_42_dialog_content = "Se especializan en productos hechos a mano. Su porcelana es de la más alta calidad, al igual que sus abanicos plegables.",
  ui_story_5010_50100201_43_dialog_content = "¿Quizás está interesado en hacer negocios con la familia Lin?",
  ui_story_5010_50100201_44_dialog_content = "N-No, no es eso... Me ayudaron con algo muy importante en el pasado, así que quería pasar a saludarlos.",
  ui_story_5010_50100201_45_dialog_content = "Ya veo. El Lin Guild Hall está de camino a nuestra sede...",
  ui_story_5010_50100201_46_dialog_content = "¡Gran! Ah, cierto... ¿Qué tipo de papeleo debe hacerse en la sede?",
  ui_story_5010_50100201_47_dialog_content = "Es bastante simple, de verdad. Se le dará todo el tiempo del mundo para revisar cada libro de contabilidad y activos también. Por favor, tranquilízate.",
  ui_story_5010_50100201_48_dialog_content = "Bueno. Solo espero que no esté muy lejos...",
  ui_story_5010_50100201_49_dialog_content = "Estaremos allí en breve, te lo aseguro...",
  ui_story_5010_50100201_50_dialog_content = "Esperar. Frankel siente que algo anda mal.",
  ui_story_5010_50100201_51_dialog_content = "Frankel?",
  ui_story_5010_50100201_52_dialog_content = "mi conocido",
  ui_story_5010_50100201_53_dialog_content = "Parece que han captado un olor desagradable... Uno familiar.",
  ui_story_5010_50100201_54_dialog_content = "Puedo sentirlos también... ¡¡Eclipsitos!!",
  ui_story_5010_50100201_55_dialog_content = "¡Guau! ¡Guau!",
  ui_story_5010_50100201_56_dialog_content = "¡Cuidado, Betel!",
  ui_story_5010_50100201_57_dialog_content = "Puedo sentirlos... Los Eclipsites se están acercando a nuestra posición, ¡y rápido!",
  ui_story_5010_50100201_58_dialog_content = "¿Puedes percibir sus movimientos tan claramente? ¡Este debe ser el poder de los Caelestitas!",
  ui_story_5010_50100201_59_dialog_content = "Está seguro...",
  ui_story_5010_50100201_60_dialog_content = "Erradicaré a cada uno de ellos.",
  ui_story_5010_50100202_1_dialog_content = "No se sentía como si estuvieran vagando por ahí. Bastante...",
  ui_story_5010_50100202_2_dialog_content = "Era casi como si fueran directamente a su objetivo.",
  ui_story_5010_50100202_3_dialog_content = "Por objetivo, quiero decir que eres tú, ¿no? PlayerName?",
  ui_story_5010_50100202_4_dialog_content = "Yo...",
  ui_story_5010_50100202_5_dialog_content = "Espera... ¡Hay más de ellos!",
  ui_story_5010_50100202_6_dialog_content = "Graaaaaaagh!!",
  ui_story_5010_50100202_7_dialog_content = "¡Me quedo con los de delante! ¡Quédate detrás de mí por ahora!",
  ui_story_5010_50100202_8_dialog_content = "¡Aviso!",
  ui_story_5010_50100202_9_dialog_content = "gra-",
  ui_story_5010_50100202_10_dialog_content = "¿Qué es esto? ¿Sigues en pie después de todo eso? Eres un poco diferente de lo que dicen los rumores, Caelestite.",
  ui_story_5010_50100202_11_dialog_content = "... ¿E-Has estado siguiéndonos todo este tiempo?",
  ui_story_5010_50100202_12_dialog_content = "un miembro de la <color=#FFB400>Mercenarios de la Llama Blanca</color>? Así que... Incluso contrataste a un guardaespaldas.",
  ui_story_5010_50100202_13_dialog_content = "Para ocultar tu presencia tan bien todo este tiempo... Estoy agradecido de que no seas nuestro enemigo.",
  ui_story_5010_50100202_14_dialog_content = "Yo soy <color=#FFB400>Lucas</color>, de los Mercenarios de la Llama Blanca. Recibí una solicitud de Naroxel para protegerte, PlayerName.",
  ui_story_5010_50100202_15_dialog_content = "¿Protegeme?",
  ui_story_5010_50100202_16_dialog_content = "¡Así es! Naroxel dice que eres un buen amigo suyo y que la ayudaste en el pasado.",
  ui_story_5010_50100202_17_dialog_content = "... PlayerName, también he pedido que Luke, un viejo amigo mío, venga en tu ayuda...",
  ui_story_5010_50100202_18_dialog_content = "¡Pero Umbraton no es una zona de guerra! ¿Por qué necesitaría protección?",
  ui_story_5010_50100202_19_dialog_content = "Oye, solo soy un mercenario. Nunca hago preguntas.",
  ui_story_5010_50100202_20_dialog_content = "Ejem...",
  ui_story_5010_50100202_21_dialog_content = "¡Ay! Buenos días, Lady Bethel del Gremio. ¡Después de todo, tal destreza de combate es de esperar del sucesor de Lord Istvan!",
  ui_story_5010_50100202_22_dialog_content = "Mmm...",
  ui_story_5010_50100202_23_dialog_content = "Espera... Lucas. ¿Sabe algo acerca de las subastas clandestinas?",
  ui_story_5010_50100202_24_dialog_content = "No mucho, pero siempre podría recopilar información para ti, si quieres.",
  ui_story_5010_50100202_25_dialog_content = "¿En serio? ¡Eso sería genial! Mira, quiero ir a la subasta para saber si...",
  ui_story_5010_50100202_26_dialog_content = "PlayerName¡Creo que primero deberíamos regresar a la sede para atender nuestra primera orden del día!",
  ui_story_5010_50100202_27_dialog_content = "¿Seguirás escoltándonos desde atrás, Luke? Creo que no hay razón para mantenerse oculto ahora.",
  ui_story_5010_50100202_28_dialog_content = "Je, lo siento. Sólo un viejo hábito en mi línea de trabajo...",
  ui_story_5010_50100202_29_dialog_content = "¡Derribamos la aeronave del cielo!",
  ui_story_5010_50100202_30_dialog_content = "¡Bueno! ¡Continúa la búsqueda! ¡Asegúrate de que los muertos estén muertos y tráeme el resto!",
  ui_story_5010_50100202_31_dialog_content = "Rin...",
  ui_story_5010_50100202_32_dialog_content = "¿Mmm?",
  ui_story_5010_50100202_33_dialog_content = "¿Cómo van las cosas?",
  ui_story_5010_50100202_34_dialog_content = "Todo según el plan.",
  ui_story_5010_50100301_1_dialog_content = "¡Guau, los edificios en Umbraton son muy distintivos!",
  ui_story_5010_50100301_2_dialog_content = "Pero de alguna manera se siente mucho más sofocante en la ciudad.",
  ui_story_5010_50100301_3_dialog_content = "Que fastidio... Decían que iba a llover, pero en todo este tiempo no nos ha caído ni una gota.",
  ui_story_5010_50100301_4_dialog_content = "Ah...!",
  ui_story_5010_50100301_5_dialog_content = "¡Mira mira! ¡Un nuevo torneo está a punto de comenzar!",
  ui_story_5010_50100301_6_dialog_content = "¿Eh? Un volante...?",
  ui_story_5010_50100301_7_dialog_content = "Déjame ver... Ah, es para el Underground Arena.",
  ui_story_5010_50100301_8_dialog_content = "Arena Subterránea...?",
  ui_story_5010_50100301_9_dialog_content = "Son partidos privados, por lo que se consideran clandestinos. Algo así como esa subasta que mencionaste antes.",
  ui_story_5010_50100301_10_dialog_content = "Las reglas para estas peleas indescriptibles son simples. Vence a tu oponente usando cualquier medio necesario y ganas.",
  ui_story_5010_50100301_11_dialog_content = "Y si matas a tu oponente... No eres responsable de nada.",
  ui_story_5010_50100301_12_dialog_content = "Wow... Pero suena tan brutal. Cómo...",
  ui_story_5010_50100301_13_dialog_content = "Bueno, es cierto que estas peleas son completamente ilegales... Pero esto sigue siendo Umbraton.",
  ui_story_5010_50100301_14_dialog_content = "Entonces... ¿todos están dispuestos a arriesgar sus vidas por las recompensas?",
  ui_story_5010_50100301_15_dialog_content = "No exactamente, no. Para los verdaderos luchadores, estos combates clandestinos son los campos de entrenamiento perfectos...",
  ui_story_5010_50100301_16_dialog_content = "Ese edificio es el Lin Guild Hall, PlayerName.",
  ui_story_5010_50100301_17_dialog_content = "¿Es esta una de sus tiendas? Se ve especial, eso es seguro.",
  ui_story_5010_50100301_18_dialog_content = "En efecto. Al igual que sus productos, es un testimonio de su exquisita artesanía.",
  ui_story_5010_50100301_19_dialog_content = "Solo hay un guardia apostado en la entrada, así como un aviso que dice que la tienda está cerrada hoy.",
  ui_story_5010_50100301_20_dialog_content = "Ah... que pena... Parece que tendré que esperar hasta la próxima vez para verlos.",
  ui_story_5010_50100301_21_dialog_content = "Ahora bien, si no hay nada más, por favor síganme a nuestra sede, PlayerName.",
  ui_story_5010_50100301_22_dialog_content = "...Okey.",
  ui_story_5010_50100301_23_dialog_content = "Ah... Parece que la Verdad me ha llevado hasta ti hoy, Luke.",
  ui_story_5010_50100301_24_dialog_content = "Oh, tú... Supongo que todo salió bien, ¿entonces?",
  ui_story_5010_50100301_25_dialog_content = "Naturalmente...",
  ui_story_5010_50100301_26_dialog_content = "E-Espera, ¿ustedes dos se conocen?",
  ui_story_5010_50100301_27_dialog_content = "Mucho tiempo sin verlo, PlayerName. Diría que nuestro encuentro es una bendición de la Verdad...",
  ui_story_5010_50100301_28_dialog_content = "Pero Umbraton nunca ha sido un lugar tan simple. Rezo para que estés alerta a los peligros que te rodean... Tanto los visibles como los invisibles.",
  ui_story_5010_50100301_29_dialog_content = "¿Dejarías de hablar en acertijos? ¿Cómo podría estar alerta a las cosas que no puedo ver en primer lugar?",
  ui_story_5010_50100301_30_dialog_content = "No te preocupes por eso. Me tienes a tu lado, así como a Bethel.",
  ui_story_5010_50100301_31_dialog_content = "En efecto. Te garantizo que estarás perfectamente a salvo en Umbraton bajo mi vigilancia, PlayerName.",
  ui_story_5010_50100301_32_dialog_content = "Ah, sí, escuchar esto me tranquiliza.",
  ui_story_5010_50100301_33_dialog_content = "Hasta que nos encontremos la próxima vez, PlayerName.",
  ui_story_5010_50100301_34_dialog_content = "¿Qué te dio Fausto, Luke?",
  ui_story_5010_50100301_35_dialog_content = "Hmm... Una sorpresa, se podría decir. Lo descubrirás muy pronto.",
  ui_story_5010_50100301_36_dialog_content = "... Espero que ustedes dos se diviertan con esto.",
  ui_story_5010_50100301_37_dialog_content = "Finalmente hemos llegado. Bienvenido a la sede del gremio de Umbraton.",
  ui_story_5010_50100301_38_dialog_content = "Esto no se parece en nada a un gremio... ¡Parece una fortaleza! No es de extrañar que Luke diga que la gente evita causar problemas por aquí...",
  ui_story_5010_50100301_39_dialog_content = "Señora Betel.",
  ui_story_5010_50100301_40_dialog_content = "Buen día. ¿Alguna noticia del Señor de las Sombras?",
  ui_story_5010_50100301_41_dialog_content = "Todavía no, mi señora.",
  ui_story_5010_50100301_42_dialog_content = "Iré a traer los materiales necesarios. Por favor, espere un momento.",
  ui_story_5010_50100301_43_dialog_content = "Como desee, mi señora. Por aqui por favor.",
  ui_story_5010_50100301_44_dialog_content = "(¡E-Todos son tan corteses por aquí! ¿Cómo debo reaccionar?)",
  ui_story_5010_50100301_45_dialog_content = "... No necesitas inclinarte, PlayerName.",
  ui_story_5010_50100301_46_dialog_content = "Este lugar me pone nervioso.",
  ui_story_5010_50100301_47_dialog_content = "Te esperaré afuera.",
  ui_story_5010_50100301_48_dialog_content = "Mis disculpas por la espera, PlayerName. Aquí está el libro de activos, así como la documentación relevante. Por favor, léalas todo el tiempo que desee.",
  ui_story_5010_50100301_49_dialog_content = "¿Dónde ha ido Lucas?",
  ui_story_5010_50100301_50_dialog_content = "Acaba de salir hace unos segundos... ¡Vaya! ¡Esto es mucho papeleo!",
  ui_story_5010_50100301_51_dialog_content = "Mis disculpas. El proceso es algo complicado. Haré todo lo posible para simplificarlo, pero ciertos lugares aún requerirán su firma.",
  ui_story_5010_50100301_52_dialog_content = "Aquí, por ejemplo. Y aquí. Y aquí...",
  ui_story_5010_50100301_53_dialog_content = "¿Necesitas que te explique algo de esto?",
  ui_story_5010_50100301_54_dialog_content = "¡G-Graaah...!",
  ui_story_5010_50100301_55_dialog_content = "¡Ah! HH-Se acaba de convertir en un...",
  ui_story_5010_50100301_56_dialog_content = "PlayerName! ¡Hay un Eclipsite en la entrada principal!",
  ui_story_5010_50100301_57_dialog_content = "¡¿?!",
  ui_story_5010_50100301_58_dialog_content = "¡¿Cómo apareció de repente un eclipse aquí?!",
  ui_story_5010_50100301_59_dialog_content = "¡Evacuar a los civiles es nuestra principal prioridad! ¡Cierra la puerta principal y escolta a todos por la parte de atrás!",
  ui_story_5010_50100301_60_dialog_content = "¡Entendido!",
  ui_story_5010_50100301_61_dialog_content = "Tienes algo de valor... ¡Metiendo problemas frente al Gremio!",
  ui_story_5010_50100301_62_dialog_content = "¡Hay más!",
  ui_story_5010_50100301_63_dialog_content = "¡Lucha, Frankel!",
  ui_story_5010_50100301_64_dialog_content = "Ponte detrás de mí, PlayerName!",
  ui_story_5010_50100401_1_dialog_content = "¡Señora Betel!",
  ui_story_5010_50100401_2_dialog_content = "¿Estás...? ¡Oh, gracias a Dios que estás bien, milady!",
  ui_story_5010_50100401_3_dialog_content = "¿Dónde están los guardias? ¿Por qué hay tan poca gente aquí?",
  ui_story_5010_50100401_4_dialog_content = "¡N-No se preocupe, Lady Bethel! ¡Encontraré más ayuda! ¡Déjame esto a mi!",
  ui_story_5010_50100401_5_dialog_content = "¿Eran tus hombres, Bethel?",
  ui_story_5010_50100401_6_dialog_content = "Sí, ¿qué hay de eso?",
  ui_story_5010_50100401_7_dialog_content = "Estas personas no parecen tener ninguna experiencia de combate. Solo míralos, todos están muertos de miedo.",
  ui_story_5010_50100401_8_dialog_content = "Mmm...",
  ui_story_5010_50100401_9_dialog_content = "¡Espera!",
  ui_story_5010_50100401_10_dialog_content = "¿Has descubierto algo?",
  ui_story_5010_50100401_11_dialog_content = "¡Ese rincón! ¡Hay algo ahí!",
  ui_story_5010_50100401_12_dialog_content = "... Frankel, ve a ver qué hay más adelante.",
  ui_story_5010_50100401_13_dialog_content = "¡Guau!",
  ui_story_5010_50100401_14_dialog_content = "¡Graagh!",
  ui_story_5010_50100401_15_dialog_content = "¡Guau! ¡Guau!",
  ui_story_5010_50100401_16_dialog_content = "Eso fue rápido, ¿no?",
  ui_story_5010_50100401_17_dialog_content = "¡¡Graaaaaah!!",
  ui_story_5010_50100401_18_dialog_content = "De mente simple, de todos modos. Enviar a Frankel por delante fue todo lo que se necesitó para sacarlo.",
  ui_story_5010_50100401_19_dialog_content = "Gracias por la advertencia, PlayerName. Eres muy perceptivo.",
  ui_story_5010_50100401_20_dialog_content = "¿Estás seguro de que esto es una emboscada? ¡Todavía siento muchos de ellos cerca! Mantente en guardia...",
  ui_story_5010_50100401_21_dialog_content = "¡Acepta tu castigo!",
  ui_story_5010_50100401_22_dialog_content = "Graaaaaaaaaa...!",
  ui_story_5010_50100401_23_dialog_content = "<color=#FFB400>Pittman</color>!",
  ui_story_5010_50100401_24_dialog_content = "Lumopolis... ¿Por qué han considerado oportuno enviar a alguien del Salón de la Justicia aquí?",
  ui_story_5010_50100401_25_dialog_content = "El olor de esta criatura... Gracias a él, finalmente pude encontrar este lugar.",
  ui_story_5010_50100401_26_dialog_content = "Ese es Wayne Pittman, un investigador del Salón de la Justicia. Una vez luchamos codo con codo, Bethel.",
  ui_story_5010_50100401_27_dialog_content = "Saludos, Sr. Pittman de Lumopolis. Soy Bethel, el jefe del Gremio Umbraton.",
  ui_story_5010_50100401_28_dialog_content = "¿Estabas buscando algo aquí en Umbraton? Si estabas buscando el camino de regreso a Lumopolis, estaría feliz de mostrártelo.",
  ui_story_5010_50100401_29_dialog_content = "... Tenga la seguridad de que no estoy aquí con malas intenciones. Mi investigación actual no tiene nada que ver con ninguno de ustedes.",
  ui_story_5010_50100401_30_dialog_content = "Los eclipses de hace un momento... ¿Alguno de ustedes vio exactamente cómo aparecieron aquí?",
  ui_story_5010_50100401_31_dialog_content = "Fue muy repentino y los guardias no pudieron responder a tiempo. Estos eclipses eran más poderosos de lo habitual y parecían estar bastante familiarizados con el cuartel general.",
  ui_story_5010_50100401_32_dialog_content = "Estaba parado afuera. De hecho, vi a una persona ordinaria convertirse repentinamente en una...",
  ui_story_5010_50100401_33_dialog_content = "Hmm... Justo como pensaba.",
  ui_story_5010_50100401_34_dialog_content = "<color=#FFB400>Potenciadores</color>.",
  ui_story_5010_50100401_35_dialog_content = "Lo siento, ¿En-qué?",
  ui_story_5010_50100401_36_dialog_content = "Cuando aparecieron estos eclipses, ¿alguno de ellos exhibió un comportamiento extraño o errático?",
  ui_story_5010_50100401_37_dialog_content = "Realmente no vi nada. ¿Y tú, Betel?",
  ui_story_5010_50100401_38_dialog_content = "En un momento, Frankel ha detectado algo...",
  ui_story_5010_50100401_39_dialog_content = "Graaaaaaagh!!",
  ui_story_5010_50100401_40_dialog_content = "Una pena... Acabo de perder otra oportunidad de verlo usar el potenciador.",
  ui_story_5010_50100401_41_dialog_content = "¿Quizás si lo abrimos, aún podríamos descubrir algo?",
  ui_story_5010_50100401_42_dialog_content = "¿No vas a ayudar, Luke?",
  ui_story_5010_50100401_43_dialog_content = "Mi trabajo es protegerte, no ayudar a un oficial de Lumopolis o pelear sus batallas.",
  ui_story_5010_50100402_1_dialog_content = "Gracias por su ayuda, Sr. Pittman.",
  ui_story_5010_50100402_2_dialog_content = "Pero, ¿cómo lo hicieron exactamente? ¿Cómo podría su velocidad y poder aumentar de repente?",
  ui_story_5010_50100402_3_dialog_content = "A lo que nos referimos como potenciador. Es una droga poderosa que otorga a los Aurorianos el poder de un Eclipsite, aunque solo sea por un corto tiempo.",
  ui_story_5010_50100402_4_dialog_content = "Sin embargo, lo más preocupante es que aquellos que ingieren esos potenciadores se convertirán ellos mismos en Eclipsites.",
  ui_story_5010_50100402_5_dialog_content = "No es de extrañar que los que esperaban para tendernos una emboscada no pudieran evitarlo una vez que Frankel pasó por delante... Supongo que no tienen mucho tiempo para la paciencia.",
  ui_story_5010_50100402_6_dialog_content = "Eso significa que, si hubiéramos sido nosotros los que pasamos junto a ellos... Habríamos estado en un verdadero problema.",
  ui_story_5010_50100402_7_dialog_content = "Vaya, eso estuvo cerca... ¡Estoy de vuelta, Lady Bethel! Parece que los Eclipsites han sido casi exterminados...",
  ui_story_5010_50100402_8_dialog_content = "¡Señora Betel! ¡Estaban aquí!",
  ui_story_5010_50100402_9_dialog_content = "¡Cuiden este lugar, todos ustedes! ¡Seth!",
  ui_story_5010_50100402_10_dialog_content = "¡Sí, mi sra.!",
  ui_story_5010_50100402_11_dialog_content = "¡Ve al Señor de las Sombras y solicita más guardias!",
  ui_story_5010_50100402_12_dialog_content = "¡Entendido!",
  ui_story_5010_50100402_13_dialog_content = "El uso de un potenciador para transformar y aumentar temporalmente el poder de combate... ¿Te suena familiar esto? PlayerName?",
  ui_story_5010_50100402_14_dialog_content = "¿Podría ser?",
  ui_story_5010_50100402_15_dialog_content = "Está. Desde el día en que nos separamos en Eraveil, he estado investigando estas transformaciones...",
  ui_story_5010_50100402_16_dialog_content = "Y finalmente, mi investigación me ha llevado aquí, a Umbraton...",
  ui_story_5010_50100402_17_dialog_content = "Tal como está, los efectos de este potenciador son sorprendentemente similares a la modificación grotesca que conocimos antes. Por lo tanto, es probable que compartan un origen.",
  ui_story_5010_50100402_18_dialog_content = "¿Podría estar en Umbraton el origen de estas artes oscuras y retorcidas?",
  ui_story_5010_50100402_19_dialog_content = "No creo que este potenciador sea de Umbraton, Sr. Pittman. Estoy a cargo del gremio Umbraton, ¡y nunca he oído hablar de él!",
  ui_story_5010_50100402_20_dialog_content = "Acordado. No he oído ni un susurro sobre algo como esto.",
  ui_story_5010_50100402_21_dialog_content = "Además, los ataques de Eclipsite no son exactamente infrecuentes por aquí. Esto es Umbraton, no un paraíso cómodo en el cielo.",
  ui_story_5010_50100402_22_dialog_content = "En cualquier caso, agradezco que estés ileso. PlayerName. Nunca podría explicárselo al Señor de las Sombras si algo te sucediera.",
  ui_story_5010_50100402_23_dialog_content = "Señor de las sombras... Señor de las sombras... Sí, eso me recuerda.",
  ui_story_5010_50100402_24_dialog_content = "¿De qué estás hablando ahora, Pittman?",
  ui_story_5010_50100402_25_dialog_content = "Si alguien comprende completamente los acontecimientos en Umbraton, es el mismísimo Señor de las Sombras. Debo verlo.",
  ui_story_5010_50100402_26_dialog_content = "Iré a presentar mi informe al Sr. Istvan y esperaré sus órdenes.",
  ui_story_5010_50100402_27_dialog_content = "¿Por qué está tan seguro de que Umbraton es la fuente de su problema, Pittman?",
  ui_story_5010_50100402_28_dialog_content = "Necesitas calmarte, Luke... Él también tiene su propio trabajo...",
  ui_story_5010_50100402_29_dialog_content = "Arreglemos las cosas en lugar de pelear aquí.",
  ui_story_5010_50100402_30_dialog_content = "Tenemos enemigos que pueden convertirse en Eclipsites ahora, pero aún se desconocen sus números y motivos.",
  ui_story_5010_50100402_31_dialog_content = "Dadas nuestras circunstancias actuales, PlayerName... Creo que debemos posponer nuestro negocio anterior hasta una fecha posterior. ¿Es eso aceptable?",
  ui_story_5010_50100402_32_dialog_content = "Para ser honesto, probablemente sería mucho más fácil dejarlos aquí que llevarlos por todos lados.",
  ui_story_5010_50100402_33_dialog_content = "Acordado. Voy a ir a la estación para ver si alguna persona extraña ha aparecido en la ciudad últimamente.",
  ui_story_5010_50100402_34_dialog_content = "¿La estación?",
  ui_story_5010_50100402_35_dialog_content = "Es el lugar de referencia para obtener información por aquí.",
  ui_story_5010_50100402_36_dialog_content = "Tampoco creo que esté muy lejos de aquí... ¿Por qué no vienes conmigo? PlayerName? No puedo dejarte sola, de todos modos.",
  ui_story_5010_50100402_37_dialog_content = "Disculpe, ¿podría preguntar sobre los potenciadores en su estación?",
  ui_story_5010_50100402_38_dialog_content = "Tal vez, pero no puedo decirlo con certeza. Sin embargo, no estaría de más probar suerte.",
  ui_story_5010_50100402_39_dialog_content = "Hay una intersección en el centro del pueblo, donde cuelgan luces azules sobre las calles. El lugar al que vamos es un bar en la esquina de la calle, convenientemente llamado The Crossroads.",
  ui_story_5010_50100402_40_dialog_content = "Que apropiado...",
  ui_story_5010_50100402_41_dialog_content = "El bar ve todo tipo de gente, así que asegúrate de estar listo antes de que entremos.",
  ui_story_5010_50100402_42_dialog_content = "Dudo que puedan ser peores que los Eclipsitas mejorados con los que luchamos hoy.",
  ui_story_5010_50100402_43_dialog_content = "Solo queremos saber quién está dando esos potenciadores. No creo que haya eclipses en un bar.",
  ui_story_5010_50100402_44_dialog_content = "protegeré PlayerName. Siéntase libre de investigar, Sr. Pittman... por su cuenta.",
  ui_story_5010_50100402_45_dialog_content = "Una intersección con luces azules... Extraño, ¿no recuerdo haber visto un lugar así antes?",
  ui_story_5010_50100402_46_dialog_content = "Sólo ha existido durante unos pocos años. ¿Tal vez todavía estabas estudiando en el extranjero cuando abrió?",
  ui_story_5010_50100402_47_dialog_content = "Entonces podemos ir juntos. Quizás aprendamos más sobre quién lanzó un ataque contra el gremio.",
  ui_story_5010_50100402_48_dialog_content = "Er... Bien, hágalo a su manera, señorita Bethel. Pero por favor, una vez que lleguemos...",
  ui_story_5010_50100402_49_dialog_content = "Ten cuidado con lo que dices y haces allí.",
  ui_story_5010_50100501_1_dialog_content = "The Crossroads puede ser un lugar complicado, por lo que lo mejor para todos es tener cuidado con sus palabras.",
  ui_story_5010_50100501_2_dialog_content = "No es un problema.",
  ui_story_5010_50100501_3_dialog_content = "Está completamente en silencio por aquí... ¿Está abierto?",
  ui_story_5010_50100501_4_dialog_content = "La luz azul está encendida, así que debería estarlo. Sin embargo, es extraño... Por lo general, puedes escuchar el alboroto desde al menos tres cuadras de distancia...",
  ui_story_5010_50100501_5_dialog_content = "En cualquier caso, mantente en guardia una vez que estemos dentro.",
  ui_story_5010_50100501_6_dialog_content = "La puerta está, de hecho, abierta...",
  ui_story_5010_50100501_X6_dialog_content = "¡Permiso!",
  ui_story_5010_50100501_7_dialog_content = "Bethel, se supone que debes ordenar del bar...",
  ui_story_5010_50100501_8_dialog_content = "...",
  ui_story_5010_50100501_9_dialog_content = "¡¿Qué miras?!",
  ui_story_5010_50100501_10_dialog_content = "¡Whoa!",
  ui_story_5010_50100501_11_dialog_content = "PlayerName! ¡Ven aquí!",
  ui_story_5010_50100501_12_dialog_content = "Tú, eh... Quizá quieras mantener tu distancia de ellos. Espérame aquí, ¿de acuerdo?",
  ui_story_5010_50100501_13_dialog_content = "Está bien... Tú eres el jefe.",
  ui_story_5010_50100501_14_dialog_content = "Buenas noches.",
  ui_story_5010_50100501_15_dialog_content = "...",
  ui_story_5010_50100501_16_dialog_content = "Soy Pittman, un investigador de Lumopolis.",
  ui_story_5010_50100501_17_dialog_content = "Me gustaría hacerles algunas preguntas a todos. Su cooperación es muy apreciada.",
  ui_story_5010_50100501_18_dialog_content = "?!?!",
  ui_story_5010_50100501_19_dialog_content = "¡W-Wayne! ¡¡No puedes preguntar de la nada así!!",
  ui_story_5010_50100501_20_dialog_content = "...",
  ui_story_5010_50100501_21_dialog_content = "...",
  ui_story_5010_50100501_22_dialog_content = "¡Guau! ¡¿Q-cuándo se acercaron tanto a nosotros?!",
  ui_story_5010_50100501_23_dialog_content = "¿Qué crees que estás haciendo? Volver, PlayerName!",
  ui_story_5010_50100501_24_dialog_content = "¿De qué tienes miedo, chico? No es como si te fuera a comer.",
  ui_story_5010_50100501_25_dialog_content = "Nuestro jefe quiere hablar con ustedes dos. Toma asiento con él, ¿quieres?",
  ui_story_5010_50100501_26_dialog_content = "...",
  ui_story_5010_50100501_27_dialog_content = "...",
  ui_story_5010_50100501_28_dialog_content = "Mucho tiempo sin verlo, Sr. Rhein.",
  ui_story_5010_50100501_29_dialog_content = "Lady Bethel... ¿Un día lento en el trabajo, supongo?",
  ui_story_5010_50100501_30_dialog_content = "No hay trabajo que hacer hoy, no con el incidente que ocurrió en la sede antes. En cuanto a ti...",
  ui_story_5010_50100501_31_dialog_content = "¿Cómo ha ido el negocio para el <color=#FFB400>Gremio del León Azul</color> ¿últimamente?",
  ui_story_5010_50100501_32_dialog_content = "Jajaja, es una vida, ya sabes! ¡Nada mas!",
  ui_story_5010_50100501_33_dialog_content = "¡No hay necesidad de ser tan tenso! ¡Solo estamos charlando, eso es todo!",
  ui_story_5010_50100501_34_dialog_content = "Entonces comencemos. ¿Sobre qué quieres conversar exactamente?",
  ui_story_5010_50100501_35_dialog_content = "¿Será por los potenciadores o por el ataque a nuestro gremio de hoy?",
  ui_story_5010_50100501_36_dialog_content = "No tengo ningún interés en charlar sobre cualquier otra cosa.",
  ui_story_5010_50100501_37_dialog_content = "¿Qué es esto? ¿Una charla mientras bebíamos con el director del Gremio del León Azul y no me invitaron? Pensé que estábamos juntos aquí, ¿sabes?",
  ui_story_5010_50100501_38_dialog_content = "Un mercenario de la Llama Blanca, un investigador del Salón de la Justicia, el jefe del Gremio Umbraton y...",
  ui_story_5010_50100501_39_dialog_content = "... Un enano indefenso que no puede usar ninguna forma de Luminatics.",
  ui_story_5010_50100501_40_dialog_content = "Menudo grupo variopinto tienes aquí, Lady Bethel.",
  ui_story_5010_50100501_41_dialog_content = "No nos impidió acabar con una legión de eclipses antes, ya sabes...",
  ui_story_5010_50100501_42_dialog_content = "Así es.",
  ui_story_5010_50100501_43_dialog_content = "Lo siento, pero no estaba hablando contigo, Luke. El jefe de una pandilla de perros mercenarios desaparecida sigue siendo solo un perro, así que ¿por qué no masticas un hueso y nos dejas hablar a nosotros?",
  ui_story_5010_50100501_44_dialog_content = "¡¡!!",
  ui_story_5010_50100501_45_dialog_content = "Rhein.",
  ui_story_5010_50100501_46_dialog_content = "Estamos aquí para encontrar información, no para pelear. Si no tiene nada que dar, creo que hay muchas personas con las que podemos hablar.",
  ui_story_5010_50100501_47_dialog_content = "Yo no. No he oído nada en toda la noche.",
  ui_story_5010_50100501_48_dialog_content = "En ese caso, este chat termina aquí.",
  ui_story_5010_50100501_49_dialog_content = "Vamos, Betel.",
  ui_story_5010_50100501_50_dialog_content = "...",
  ui_story_5010_50100501_51_dialog_content = "Uf, eso fue intenso. Simplemente ignoró a un investigador de Lumopolis... Realmente no le tienen miedo a la ley, ¿verdad?",
  ui_story_5010_50100501_52_dialog_content = "Bueno, el Gremio del León Azul es realmente poderoso. Han acumulado dinero y mano de obra en exceso últimamente...",
  ui_story_5010_50100501_53_dialog_content = "Pero su negocio nunca hubiera prosperado sin la Sede del Gremio. Después de todo, todas las rutas comerciales están bajo nuestro control.",
  ui_story_5010_50100501_54_dialog_content = "...",
  ui_story_5010_50100501_55_dialog_content = "¿Estás bien, Lucas?",
  ui_story_5010_50100501_56_dialog_content = "Rhein nunca ha sido muy aficionado a nosotros, los mercenarios, pero el Gremio del León Azul es demasiado poderoso ahora... Realmente no podemos hacerle nada.",
  ui_story_5010_50100501_57_dialog_content = "Escuché que ha abierto algunas rutas comerciales no oficiales para sí mismo, y han estado acumulando ganancias.",
  ui_story_5010_50100501_58_dialog_content = "En cuanto a lo que se vende exactamente, no ha habido ningún informe al Cuartel General del Gremio al respecto...",
  ui_story_5010_50100501_59_dialog_content = "¿Qué?",
  ui_story_5010_50100501_60_dialog_content = "Parece que se necesita una investigación adecuada sobre el Gremio del León Azul.",
  ui_story_5010_50100501_61_dialog_content = "¡¡!!",
  ui_story_5010_50100501_62_dialog_content = "¿Seth? ¿Qué pasa?",
  ui_story_5010_50100501_63_dialog_content = "Sombra... Justo ahora... ¡Lo encontré!",
  ui_story_5010_50100501_64_dialog_content = "¿Qué estás tratando de decir? ¡Componga usted mismo!",
  ui_story_5010_50100501_65_dialog_content = "¡El Señor de las Sombras! ¡Él... fue atacado...!",
  ui_story_5010_50100501_66_dialog_content = "...",
  ui_story_5010_50100501_67_dialog_content = "!!!",
  ui_story_5010_50100501_68_dialog_content = "¿Templo no conformista? ¿Que esta pasando?",
  ui_story_5010_50100501_69_dialog_content = "¡Guau! ¡¡Guau guau!!",
  ui_story_5010_50100501_70_dialog_content = "Espera... ¿Quién es el que está delante?",
  ui_story_5010_50100501_71_dialog_content = "Estar atento, PlayerName!!",
  ui_story_5010_50100501_72_dialog_content = "¡Bwahahahaha!",
  ui_story_5010_50100501_73_dialog_content = "Ese olor familiar otra vez...",
  ui_story_5010_50100501_74_dialog_content = "Eso <color=#FFB400>píldora</color>... ¡No me digas...!",
  ui_story_5010_50100501_75_dialog_content = "Eso... ¡Así es! Graaaaah!",
  ui_story_5010_50100501_76_dialog_content = "Él... ¡¡¡Se convirtió en un Eclipsite!!!",
  ui_story_5010_50100501_77_dialog_content = "Bethel!",
  ui_story_5010_50100501_78_dialog_content = "¡No puedo alcanzar al Señor de las Sombras! ¡Es probable que él también esté bajo ataque!",
  ui_story_5010_50100501_79_dialog_content = "¡El enemigo está atacando! ¡Prepárate para la batalla! ... Bethel, ¿me oyes?",
  ui_story_5010_50100501_80_dialog_content = "... Draco. Yo tampoco puedo comunicarme con Seth.",
  ui_story_5010_50100501_81_dialog_content = "¡Tú y yo los mantendremos a raya, Wayne!",
  ui_story_5010_50100501_82_dialog_content = "Intenta capturar uno vivo, ¿es eso posible?",
  ui_story_5010_50100502_1_dialog_content = "Estos Eclipsites... No, son gente de Umbraton que parecen Eclipsites. ¿Es esto lo que hace la píldora...?",
  ui_story_5010_50100502_2_dialog_content = "¿Habéis visto todos la transformación con claridad? Se convierten en criaturas más poderosas que los Eclipsitas ordinarios.",
  ui_story_5010_50100502_3_dialog_content = "¿Es esta la modificación de la que hablabas antes?",
  ui_story_5010_50100502_4_dialog_content = "En rigor, es una especie de modificación, sí.",
  ui_story_5010_50100502_5_dialog_content = "¿Estás seguro de que no sabes nada más sobre estos potenciadores? ¿Umbraton realmente nunca ha experimentado este tipo de peligro en el pasado?",
  ui_story_5010_50100502_6_dialog_content = "No que yo sepa, no. Esto tiene que ser un desarrollo relativamente reciente, o de lo contrario toda la ciudad estaría en estado de pánico en este momento.",
  ui_story_5010_50100502_7_dialog_content = "Incluso ahora, sigo teniendo problemas para creerlo. Para que una persona se convierta en un Eclipsite así como así...",
  ui_story_5010_50100502_8_dialog_content = "Parece que el Gremio del León Azul está conectado de alguna manera con todo esto.",
  ui_story_5010_50100502_9_dialog_content = "Si estoy de acuerdo. Esto no puede ser solo una coincidencia.",
  ui_story_5010_50100502_10_dialog_content = "Desafortunadamente, no puedo asegurar nada sobre las identidades de estas personas en su estado transformado. Tampoco dejaron pistas atrás...",
  ui_story_5010_50100502_11_dialog_content = "Continuaré mi investigación aquí y seguiré los movimientos de Rhein por el momento.",
  ui_story_5010_50100502_12_dialog_content = "Oye... ¿Dónde está Bethel?",
  ui_story_5010_50100502_13_dialog_content = "¡Templo no conformista! ¿Dónde has estado?",
  ui_story_5010_50100502_14_dialog_content = "La situación del Señor de las Sombras aún no está clara. ¡Todo lo que sé es que ha sido atacado!",
  ui_story_5010_50100502_15_dialog_content = "Debo ir a él.",
  ui_story_5010_50100502_16_dialog_content = "¿Estás bien?",
  ui_story_5010_50100502_17_dialog_content = "Por favor perdoname, PlayerName... Tendremos que posponer aún más el asunto de su herencia. Lo discutiremos a mi regreso.",
  ui_story_5010_50100502_18_dialog_content = "Lo siento.",
  ui_story_5010_50100502_19_dialog_content = "Shadowlord fue atacado? ¿Podría ser el Gremio del León Azul...?",
  ui_story_5010_50100502_20_dialog_content = "No estoy seguro, pero nos encargaremos de nuestros propios asuntos, gracias.",
  ui_story_5010_50100502_21_dialog_content = "...",
  ui_story_5010_50100502_22_dialog_content = "Entonces, ¿cuál es el plan ahora? PlayerName?",
  ui_story_5010_50100502_23_dialog_content = "Parece que no podemos hacer mucho por ninguno de ellos en este momento.",
  ui_story_5010_50100502_24_dialog_content = "¡Correcto! ¡Aún queda la subasta clandestina!",
  ui_story_5010_50100502_25_dialog_content = "Sí, eso me recuerda... ¿Qué está buscando exactamente en esta subasta?",
  ui_story_5010_50100502_26_dialog_content = "Un conjunto de componentes de la sala de simulación. Naroxel me habló de ellos.",
  ui_story_5010_50100502_27_dialog_content = "Son partes cruciales para un Colossus, y Soroz podría usarlas.",
  ui_story_5010_50100502_28_dialog_content = "Entendido. En ese caso, haz exactamente lo que te digo una vez que lleguemos allí.",
  ui_story_5010_50100502_29_dialog_content = "¡No podemos darnos el lujo de que más cosas salgan mal hoy!",
  ui_story_5010_50100601_1_dialog_content = "Ya casi llegamos, PlayerName.",
  ui_story_5010_50100601_2_dialog_content = "Luke... ¿Q-Qué debo hacer? ¿Debería ir a hablar con el subastador?",
  ui_story_5010_50100601_3_dialog_content = "¡De ninguna manera! Cada participante en estas subastas clandestinas es completamente anónimo. Tienes que pasar por el organizador para poder acceder.",
  ui_story_5010_50100601_4_dialog_content = "Mira, el vendedor entrega sus artículos al organizador, y luego los compradores y el organizador...",
  ui_story_5010_50100601_5_dialog_content = "Oh Ahora lo entiendo. Tenemos que acercarnos al organizador y hacerle una oferta, ¿es eso?",
  ui_story_5010_50100601_6_dialog_content = "¡Como si fuera tan fácil! El organizador establecerá una subasta anónima en una fecha determinada y la venta se adjudicará al mejor postor.",
  ui_story_5010_50100601_7_dialog_content = "¿En una fecha determinada? Así que tenemos que esperar a que se lleve a cabo la subasta...",
  ui_story_5010_50100601_8_dialog_content = "No exactamente. Podemos ir a buscar al organizador para sacarle algunos detalles. Con un poco de suerte, incluso podríamos llegar a ver los productos...",
  ui_story_5010_50100601_9_dialog_content = "Entiendo. Entonces solo es cuestión de presentarse a la subasta y hacer una oferta alta por ellos, ¿verdad?",
  ui_story_5010_50100601_10_dialog_content = "Como ya he dicho, PlayerName, los compradores en estas subastas también deben mantener el anonimato total... Así que si quieres pujar por algo, el proceso es un poco más complicado que eso.",
  ui_story_5010_50100601_11_dialog_content = "¿Anonimato total? ¿Incluso para los compradores?",
  ui_story_5010_50100601_12_dialog_content = "¡Por supuesto! Si logras comprar algo valioso y todos saben quién eres, básicamente estás pidiendo que te roben... O algo peor.",
  ui_story_5010_50100601_13_dialog_content = "De todos modos, me llevaría horas explicarlo todo. Sería mejor para nosotros ir a echar un vistazo primero.",
  ui_story_5010_50100601_14_dialog_content = "Está bien, Lucas.",
  ui_story_5010_50100601_15_dialog_content = "Aquí hay una lista de artículos que se venderán pronto, así como sus fechas de subasta. Echar un vistazo, PlayerName.",
  ui_story_5010_50100601_16_dialog_content = "Esa persona de ahora...",
  ui_story_5010_50100601_17_dialog_content = "No importa.",
  ui_story_5010_50100601_18_dialog_content = "Probablemente no organicen una subasta para los componentes de la sala de simulación que está buscando en el corto plazo. Tal vez podamos intentar preguntar primero el precio inicial del vendedor.",
  ui_story_5010_50100601_19_dialog_content = "Las cosas en esta lista... ¿Cómo...? ¿Cómo podría alguien siquiera pensar en...?",
  ui_story_5010_50100601_20_dialog_content = "Jajajaja! ¡Hay una razón por la que esta es una subasta clandestina, ya sabes!",
  ui_story_5010_50100601_21_dialog_content = "¿Cómo se encuentran con este tipo de cosas?",
  ui_story_5010_50100601_22_dialog_content = "Hmm... Eso es asunto del vendedor, nadie lo sabe. Podrían haberlo excavado, o hacerlo ellos mismos... O podrían haberlo robado.",
  ui_story_5010_50100601_23_dialog_content = "Espera... ¡¿Así que a nadie le importa cómo encontraron estas cosas?!",
  ui_story_5010_50100601_24_dialog_content = "Ja, ¿qué te parece?",
  ui_story_5010_50100601_25_dialog_content = "¿Y a la gente no le preocupa dar las cosas que tienen en secreto a los organizadores de la subasta?",
  ui_story_5010_50100601_26_dialog_content = "Bueno, la subasta clandestina ha estado aquí durante años. Tienen cierto grado de credibilidad, ¿sabes?",
  ui_story_5010_50100601_27_dialog_content = "Está bastante ocupado... ¿Todas estas personas están aquí para ver los productos en subasta?",
  ui_story_5010_50100601_28_dialog_content = "¡Mantenerla baja!",
  ui_story_5010_50100601_29_dialog_content = "A juzgar por el comportamiento de todos, parece que están aquí para ofertar en la subasta de hoy.",
  ui_story_5010_50100601_30_dialog_content = "Hay un montón de gente aquí... muchos de ellos son los peces gordos de Umbraton.",
  ui_story_5010_50100601_31_dialog_content = "... ¿Eh? Esa gente de ahí...",
  ui_story_5010_50100601_32_dialog_content = "¿Fausto? ¿Y Berilo? ... ¡¿Incluso Paloma también?!",
  ui_story_5010_50100601_33_dialog_content = "Whoa... Me sorprendió descubrir que conocías a Faust, PlayerName...",
  ui_story_5010_50100601_34_dialog_content = "Pero nunca hubiera imaginado que también conocías a esas damas de la Orden Verdadera.",
  ui_story_5010_50100601_35_dialog_content = "Es una larga historia, eso es seguro...",
  ui_story_5010_50100601_36_dialog_content = "<color=#e8d9bb>Golpeteo de pitter...</color>",
  ui_story_5010_50100601_37_dialog_content = "Está empezando a llover...? ¡Vamos, Luke, entremos!",
  ui_story_5010_50100601_38_dialog_content = "Si seguro.",
  ui_story_5010_50100601_39_dialog_content = "Así que por fin llueve...",
  ui_story_5010_50100601_40_dialog_content = "...",
  ui_story_5010_50100601_41_dialog_content = "...",
  ui_story_5010_50100601_42_dialog_content = "...",
  ui_story_5010_50100601_43_dialog_content = "(Hay tanto silencio...)",
  ui_story_5010_50100601_44_dialog_content = "De esta manera, PlayerName. Ahí es donde se realizan las subastas. Estamos buscando al organizador, ¿recuerdas?",
  ui_story_5010_50100601_45_dialog_content = "Por cierto... ¿Serás capaz de decir si estas partes son falsas o no? PlayerName?",
  ui_story_5010_50100601_46_dialog_content = "El organizador dice que las piezas han sido evaluadas por técnicos tanto de Illumina como de Rediesel Wrench. Aquí está el certificado.",
  ui_story_5010_50100601_47_dialog_content = "Eh, no es broma...",
  ui_story_5010_50100601_48_dialog_content = "Ambas personas son amigos míos, Luke. Estos deben ser el verdadero negocio!",
  ui_story_5010_50100601_49_dialog_content = "Muy bien, entonces parece que el siguiente paso es registrarse en su subasta como compradores potenciales.",
  ui_story_5010_50100601_50_dialog_content = "Entonces, ¿cuánto estás dispuesto a gastar en estas piezas? PlayerName?",
  ui_story_5010_50100601_51_dialog_content = "... <size=45>678 ¿Nightium?</size>",
  ui_story_5010_50100601_52_dialog_content = "Uh... B-Bueno... Eso debería ser alrededor de una milésima parte del precio de venta del vendedor...",
  ui_story_5010_50100601_53_dialog_content = "P-Pero ese es todo el dinero que tengo ahora mismo...",
  ui_story_5010_50100601_54_dialog_content = "Ya veo... Parece que tendremos que volver atrás y pensar en otra cosa.",
  ui_story_5010_50100601_55_dialog_content = "Afortunadamente, la subasta de esos componentes no comenzará por un tiempo.",
  ui_story_5010_50100601_56_dialog_content = "Derecho...",
  ui_story_5010_50100601_57_dialog_content = "Yo no me preocuparía demasiado por eso. Si podemos encontrar algo de valor lo suficientemente alto, podríamos negociar con el vendedor...",
  ui_story_5010_50100601_58_dialog_content = "<size=45><color=#e8d9bb>¡Golpe!</color></size>",
  ui_story_5010_50100601_59_dialog_content = "¿Qué fue ese ruido de hace un momento?",
  ui_story_5010_50100601_60_dialog_content = "Vino de la sala de subastas... Tengo un mal presentimiento sobre esto.",
  ui_story_5010_50100601_61_dialog_content = "¡Vamos, vamos a echar un vistazo!",
  ui_story_5010_50100601_62_dialog_content = "¡E-espere, señor! No puedes simplemente...",
  ui_story_5010_50100601_63_dialog_content = "¿No puede simplemente qué? ¿Hacer esto?",
  ui_story_5010_50100601_64_dialog_content = "<size=45><color=#e8d9bb>¡Golpe! ¡Golpe!</color></size>",
  ui_story_5010_50100601_65_dialog_content = "¡¿Disparos?!",
  ui_story_5010_50100601_66_dialog_content = "¡Bajar! no te muevas...",
  ui_story_5010_50100601_67_dialog_content = "Siento interrumpir a todos...",
  ui_story_5010_50100601_68_dialog_content = "¡¿Qué crees que estás haciendo?!",
  ui_story_5010_50100601_69_dialog_content = "Shh... Por favor, quédate en silencio, si quieres.",
  ui_story_5010_50100601_70_dialog_content = "Venimos a hacer un anuncio, nada más. No hay motivo para el pánico...",
  ui_story_5010_50100601_71_dialog_content = "Por favor, Maude, si me permites. He querido decir estas palabras por... Oh, tanto tiempo...",
  ui_story_5010_50100601_72_dialog_content = "Ahora bien... Desde este día en adelante, yo, Rhein, serviré como el nuevo...",
  ui_story_5010_50100601_73_dialog_content = "<color=#FFB400>Regla</color>.",
  ui_story_5010_50100601_74_dialog_content = "¡¿?!",
  ui_story_5010_50100601_75_dialog_content = "Ese tipo junto a Rhein es Maude, el líder de una pandilla local llamada Solus.",
  ui_story_5010_50100601_76_dialog_content = "Solus es una de las pandillas más poderosas aquí en Umbraton. Nunca me hubiera imaginado que se pondrían el sombrero con el Blue Lion Guild.",
  ui_story_5010_50100601_77_dialog_content = "Rhein, Maude... ¡¿De qué están hablando?!",
  ui_story_5010_50100601_78_dialog_content = "¿No te preguntamos...",
  ui_story_5010_50100601_79_dialog_content = "Para callarte la boca!!",
  ui_story_5010_50100601_80_dialog_content = "¿Por qué tienes que hacerme gritar como un humilde plebeyo...",
  ui_story_5010_50100601_81_dialog_content = "Intentemos esto de nuevo... ¡Atención a todos! ¡Una gran revolución está a punto de comenzar, y seré yo quien guíe a Umbraton hacia una gloriosa nueva era!",
  ui_story_5010_50100601_82_dialog_content = "Es un gran honor para mí discutir el futuro de Umbraton con los estimados líderes del gremio reunidos aquí hoy...",
  ui_story_5010_50100601_83_dialog_content = "En cuanto al Señor de las Sombras, de quien estoy seguro que todo el mundo está susurrando actualmente, puedo asegurarles a todos que él y su amada aeronave... son parte de la rica historia de nuestra ciudad ahora.",
  ui_story_5010_50100601_84_dialog_content = "¡¿Qué hiciste?!",
  ui_story_5010_50100601_85_dialog_content = "¿De qué está hablando, Luke?",
  ui_story_5010_50100601_86_dialog_content = "¿No lo escuchaste? ¡Rhein está iniciando una rebelión!",
  ui_story_5010_50100601_87_dialog_content = "Maldita sea... ¡Nuestras terminales no funcionan en absoluto! Esto tiene que ser obra de Rhein...",
  ui_story_5010_50100601_88_dialog_content = "¡Tenemos que encontrar una manera de difundir las noticias!",
  ui_story_5010_50100601_89_dialog_content = "Pero, ¿de dónde viene la confianza de Rhein? ¿Realmente cree que puede vencer a todos los jefes aquí?",
  ui_story_5010_50100601_90_dialog_content = "¡Mira hacia allá, Luke!",
  ui_story_5010_50100601_91_dialog_content = "Cielos... ¡Son muchos Eclipses transformados!",
  ui_story_5010_50100601_92_dialog_content = "¡Por favor, absténgase de cualquier acto de resistencia sin sentido!",
  ui_story_5010_50100601_93_dialog_content = "Como representante del Gremio del León Azul... No, de TODO Umbraton... Acepte mis más sinceras disculpas por esta escena desordenada.",
  ui_story_5010_50100601_94_dialog_content = "Ahora bien, queridos líderes de los muchos gremios de Umbraton, así como todos los demás estimados invitados desde lejos, ¡exijo humildemente su rendición incondicional y la aceptación de los siguientes términos!",
  ui_story_5010_50100601_95_dialog_content = "Lucas, nosotros...",
  ui_story_5010_50100601_96_dialog_content = "Te cubriré mientras buscas una salida. Después de eso, depende de ti conseguir ayuda para todos nosotros.",
  ui_story_5010_50100601_97_dialog_content = "¿eh? ¡¿Qué estás haciendo?!",
  ui_story_5010_50100601_98_dialog_content = "¿...?",
  ui_story_5010_50100601_99_dialog_content = "Parece... ¡Ya no necesitas este brazo!",
  ui_story_5010_50100601_100_dialog_content = "¡¡¡Aaaaaaaargh!!!",
  ui_story_5010_50100601_101_dialog_content = "¿El verdadero orden...?",
  ui_story_5010_50100601_102_dialog_content = "...",
  ui_story_5010_50100601_103_dialog_content = "Se suponía que esto era una subasta normal, y la arruinaste...",
  ui_story_5010_50100601_104_dialog_content = "¡C-Tranquila, Paloma! Ya lo dejaste inconsciente...",
  ui_story_5010_50100601_105_dialog_content = "Sr. Rhein, las reglas prohíben cualquier tipo de interrupción ruidosa en estas subastas. Me temo... Tendremos que pedirte que te vayas.",
  ui_story_5010_50100601_106_dialog_content = "... ¿Y tú quién eres? ¿Se supone que debo saber quién eres?",
  ui_story_5010_50100601_107_dialog_content = "Basta de esta tontería. Matarlos a todos.",
  ui_story_5010_50100601_108_dialog_content = "¡Berilo! ¡Paloma!",
  ui_story_5010_50100601_109_dialog_content = "¡¿PlayerName?!",
  ui_story_5010_50100601_110_dialog_content = "Nos encontramos de nuevo, mi amigo. Una pena que tenga que ser en circunstancias tan terribles.",
  ui_story_5010_50100601_111_dialog_content = "Tú otra vez, Caelestite... Pero, ¿dónde han ido tus socios?",
  ui_story_5010_50100601_112_dialog_content = "...",
  ui_story_5010_50100601_113_dialog_content = "... Ah, pero supongo que esto era de esperar. No quería recurrir a la violencia, ¿sabes?",
  ui_story_5010_50100601_114_dialog_content = "Tch.",
  ui_story_5010_50100601_115_dialog_content = "Me desharé de los de aquí. Puedes quedarte con el resto.",
  ui_story_5010_50100601_116_dialog_content = "¡Sí señor!",
  ui_story_5010_50100601_117_dialog_content = "Toma, llévate esto también.",
  ui_story_5010_50100601_118_dialog_content = "¡Ay! ¡G-Gracias, jefe! Todas estas cosas buenas...",
  ui_story_5010_50100601_119_dialog_content = "¡No dejes que se desperdicie ni una sola pastilla! ¡Por el nuevo pedido de Umbraton!",
  ui_story_5010_50100601_120_dialog_content = "¡Graaaaaagh!",
  ui_story_5010_50100601_121_dialog_content = "Ese hombre... ¡¿Acaba de convertirse en un Eclipsite?!",
  ui_story_5010_50100601_122_dialog_content = "Pedidos, PlayerName!",
  ui_story_5010_50100601_123_dialog_content = "¡Déjamelo a mí! ¡Fausto, asegúrate de que esos dos no se escapen!",
  ui_story_5010_50100601_124_dialog_content = "¿Qué es esto? ¿Quieres capturarnos?",
  ui_story_5010_50100601_125_dialog_content = "Jajajaja! ¡Qué niño más valiente!",
  ui_story_5010_50100601_126_dialog_content = "Oye, ¿por qué te ríes? Tengo algunas preguntas para ti, ¡ahora ven aquí!",
  ui_story_5010_50100601_127_dialog_content = "Quédate atrás, loca.",
  ui_story_5010_50100601_128_dialog_content = "Como me llamaste...?",
  ui_story_5010_50100601_129_dialog_content = "*Suspiro* Esto se va a poner feo.",
  ui_story_5010_50100602_1_dialog_content = "... ¡Condenar!",
  ui_story_5010_50100602_2_dialog_content = "¡Uraaaagh...!",
  ui_story_5010_50100602_3_dialog_content = "Ah... ¡Pittman! ¡Estás aquí!",
  ui_story_5010_50100602_4_dialog_content = "¿Pittman?",
  ui_story_5010_50100602_5_dialog_content = "Buenas noches a ti también, Paloma...",
  ui_story_5010_50100602_6_dialog_content = "Cristal Sanguíneo... ¡Esto pertenece a Beryl Gautier!",
  ui_story_5010_50100602_7_dialog_content = "¡Hola! ¡He oído hablar mucho de usted, señor investigador!",
  ui_story_5010_50100602_8_dialog_content = "Señorita Beryl Gautier... Soy Wayne Pittman del Lumo Hall of Justice, debo insistir en que me acompañe en este instante...",
  ui_story_5010_50100602_9_dialog_content = "¿Estás... arrestándome?",
  ui_story_5010_50100602_10_dialog_content = "Parece que no has hecho ningún progreso en tu investigación, Pittman...",
  ui_story_5010_50100602_11_dialog_content = "Eh... ¿Paloma? Pittman no vino aquí por ustedes. Está aquí por...",
  ui_story_5010_50100602_12_dialog_content = "Los potenciadores, o más precisamente, las píldoras que esos miembros del Blue Lion Guild acaban de tragar...",
  ui_story_5010_50100602_13_dialog_content = "Espera, ¿de qué estás hablando?",
  ui_story_5010_50100602_14_dialog_content = "Paloma... Me temo que la técnica de modificación de Mirren Gautier está conectada de alguna manera con estos potenciadores.",
  ui_story_5010_50100602_15_dialog_content = "Mirren Gautier...",
  ui_story_5010_50100602_16_dialog_content = "Tenemos que parar esto ahora. Lo más importante, por ahora, no es discutir.",
  ui_story_5010_50100602_17_dialog_content = "¿Adónde se fue el Rin? ¿O ese tipo con el bastón, para el caso?",
  ui_story_5010_50100602_18_dialog_content = "Deben haberse escapado.",
  ui_story_5010_50100602_19_dialog_content = "Pero, ¿por qué elegirían esta subasta como objetivo de su ataque?",
  ui_story_5010_50100602_20_dialog_content = "Me temo que la respuesta no es tan fácil. Todo esto debe ser parte de su plan.",
  ui_story_5010_50100602_21_dialog_content = "Nos estamos quedando sin tiempo. Tenemos que...",
  ui_story_5010_50100602_22_dialog_content = "Disculpen, amigos. Pero he encontrado lo que estábamos buscando.",
  ui_story_5010_50100602_23_dialog_content = "¿Lo encontraste?",
  ui_story_5010_50100602_24_dialog_content = "Viendo que el Gremio del León Azul ya ha violado las reglas de la subasta...",
  ui_story_5010_50100602_25_dialog_content = "Supuse que podríamos conseguir lo que queremos e irnos ahora.",
  ui_story_5010_50100602_26_dialog_content = "Lo lamento muchísimo, PlayerName, pero creo que estas damas y yo debemos ir por caminos separados por ahora.",
  ui_story_5010_50100602_27_dialog_content = "Quizás nos volvamos a ver algún día pronto... Que la Verdad los bendiga.",
  ui_story_5010_50100602_28_dialog_content = "A-Adiós, PlayerName...",
  ui_story_5010_50100602_29_dialog_content = "¡Vaya! Uh, ¡cuídense, ustedes tres!",
  ui_story_5010_50100602_30_dialog_content = "Ya se han ido... ¿Todos en True Order van y vienen como el viento?",
  ui_story_5010_50100602_31_dialog_content = "¡Beryl Gautier! ¡Vuelve, Beryl Gautier...!",
  ui_story_5010_50100602_32_dialog_content = "Ah... Olvídalo. Estoy seguro de que Rhein todavía tiene más reservado para todos nosotros, PlayerName.",
  ui_story_5010_50100602_33_dialog_content = "Nuestras terminales siguen caídas...",
  ui_story_5010_50100602_34_dialog_content = "Mira allá. ¡Es una señal de humo, y viene de la dirección del cuartel general del gremio!",
  ui_story_5010_50100602_35_dialog_content = "En circunstancias normales, las tropas de la guarnición de Umbraton serían enviadas inmediatamente para controlar la situación.",
  ui_story_5010_50100602_36_dialog_content = "¿Pueden realmente las tropas de la guarnición de Umbraton derrotar a un potenciador?",
  ui_story_5010_50100602_37_dialog_content = "Er... ¿Honestamente? No creo que tengan ninguna posibilidad.",
  ui_story_5010_50100602_38_dialog_content = "Deberíamos hacer nuestro camino hacia la sede y determinar la situación.",
  ui_story_5010_50100602_39_dialog_content = "Estoy de acuerdo... ¡Dirige el camino, Luke!",
  ui_story_5010_50100602_40_dialog_content = "¡Ven conmigo!",
  ui_story_5010_50100701_1_dialog_content = "La Orden Verdadera... Son aún más problemáticos de lo que había anticipado.",
  ui_story_5010_50100701_2_dialog_content = "No obstante, el plan se pone en marcha y la victoria es casi nuestra.",
  ui_story_5010_50100701_3_dialog_content = "Parecería que sí, pero preferiría no jugar nuestra final <color=#FFB400>carta de triunfo</color>.",
  ui_story_5010_50100701_4_dialog_content = "¡Señora Betel! ¡Gracias a dios! ¡Tienes que salvar...!",
  ui_story_5010_50100701_5_dialog_content = "¡Jajajajaja!",
  ui_story_5010_50100701_6_dialog_content = "¿Quién eres? ¿Cómo te atreves a atacar el Cuartel General del Gremio Umbraton?",
  ui_story_5010_50100701_7_dialog_content = "Je... ¡Solo estamos actuando bajo la orden del nuevo Señor de las Sombras! ¡El Cuartel General del Gremio Umbraton le pertenece ahora!",
  ui_story_5010_50100701_8_dialog_content = "... ¿Tienes alguna idea de lo que acabas de decir?",
  ui_story_5010_50100701_9_dialog_content = "¡Ja, por supuesto que sí, mujer tonta! ¡¡Hoy es el día que mueres!!",
  ui_story_5010_50100701_10_dialog_content = "Parece que todos estáis preparados para morir por vuestra causa.",
  ui_story_5010_50100701_11_dialog_content = "En ese caso.",
  ui_story_5010_50100701_12_dialog_content = "... ¡¡Urgh!!",
  ui_story_5010_50100701_13_dialog_content = "Estoy feliz de complacer.",
  ui_story_5010_50100701_14_dialog_content = "No pensamos que serías tú quien respondería a nuestra señal de socorro, Lady Bethel...",
  ui_story_5010_50100701_15_dialog_content = "Había tantos de ellos en este momento. Dijeron que el nuevo Señor de las Sombras tenía el control de todo, y que nosotros...",
  ui_story_5010_50100701_16_dialog_content = "Espera... ¡Cuidado, todos!",
  ui_story_5010_50100701_17_dialog_content = "Este sentimiento... ¡El sentimiento de un poder abrumador! Jajajajaja!!!",
  ui_story_5010_50100701_18_dialog_content = "La lucha parece intensa... Los invasores ya deben haber entrado por la fuerza en el salón principal.",
  ui_story_5010_50100701_19_dialog_content = "¡Esa era la voz de Bethel hace un momento!",
  ui_story_5010_50100701_20_dialog_content = "Espera... Estoy teniendo esa extraña sensación otra vez... ¿Es...?",
  ui_story_5010_50100701_21_dialog_content = "¡Está! ¡Están usando potenciadores otra vez!",
  ui_story_5010_50100701_22_dialog_content = "Bethel!",
  ui_story_5010_50100701_23_dialog_content = "PlayerName! ¡Estoy por aquí!",
  ui_story_5010_50100701_24_dialog_content = "Diez veces... No, veinte veces... ¡Todos ustedes, miren bien!",
  ui_story_5010_50100701_25_dialog_content = "¿Cuántas pastillas tomó ese tipo?",
  ui_story_5010_50100701_26_dialog_content = "¡Ya vamos, Betel! ¡Solo espera!",
  ui_story_5010_50100801_1_dialog_content = "¡Templo no conformista! ¡Estos tipos son los hombres de Maude! ¡Él y Rhein atacaron la subasta clandestina hace un momento!",
  ui_story_5010_50100801_2_dialog_content = "Rhein dijo que el Señor de las Sombras... ya era historia.",
  ui_story_5010_50100801_3_dialog_content = "Cuando dijiste que el Señor de las Sombras había sido atacado antes, ¿qué hiciste...?",
  ui_story_5010_50100801_4_dialog_content = "Todavía no me he puesto en contacto con él, y las personas a las que ordené que lo buscaran aún no han enviado un mensaje.",
  ui_story_5010_50100801_5_dialog_content = "Todo lo que sé es que hubo un accidente con la aeronave del Señor de las Sombras...",
  ui_story_5010_50100801_6_dialog_content = "Entonces, ¿por qué estás aquí en la sede?",
  ui_story_5010_50100801_7_dialog_content = "Vi la señal de socorro a lo lejos y vine lo más rápido que pude.",
  ui_story_5010_50100801_8_dialog_content = "¡Señora Betel! Somos los primeros en responder de la guarnición...",
  ui_story_5010_50100801_9_dialog_content = "Sé que sé. ¿Nos has traído alguna novedad?",
  ui_story_5010_50100801_10_dialog_content = "El Gremio del León Azul, junto con Solus, han dado un golpe total.",
  ui_story_5010_50100801_11_dialog_content = "Los objetivos de su insurgencia armada incluyen todos los principales gremios, una subasta clandestina y la mansión del Señor de las Sombras...",
  ui_story_5010_50100801_12_dialog_content = "Ya se han implementado medidas de emergencia, y...",
  ui_story_5010_50100801_13_dialog_content = "¿Alguien ha podido ponerse en contacto con el mismísimo Señor de las Sombras?",
  ui_story_5010_50100801_14_dialog_content = "Debido al clima anormal de hoy, todas las terminales dentro de la ciudad están actualmente inoperativas. No hemos podido establecer contacto con el Señor de las Sombras, pero los rumores mencionan que Rhein ya ha...",
  ui_story_5010_50100801_15_dialog_content = "Suficiente. Continúe con su trabajo.",
  ui_story_5010_50100801_16_dialog_content = "¡Y cuidado con esos monstruos! ¡Pueden transformarse en cualquier momento!",
  ui_story_5010_50100801_17_dialog_content = "¡Que mucho! Encuentra una manera de restablecer las comunicaciones dentro de la ciudad. ¡Necesitamos determinar la situación en cada sector y rescatar a aquellos que aún pueden ser rescatados!",
  ui_story_5010_50100801_18_dialog_content = "P-Pero Lady Bethel, nuestra directiva principal es proteger el centro de la ciudad...",
  ui_story_5010_50100801_19_dialog_content = "...",
  ui_story_5010_50100801_20_dialog_content = "Lo siento, pero eran órdenes del Señor de las Sombras. Adiós, señora Bethel.",
  ui_story_5010_50100801_21_dialog_content = "Je, ese es Lord Istvan para ti.",
  ui_story_5010_50100801_22_dialog_content = "¿Han perdido la cabeza Rhein y sus hombres? ¿Cuánto poder podrían tener para tener la confianza suficiente para desafiar a todo Umbraton a la vez?",
  ui_story_5010_50100801_23_dialog_content = "Umbraton no está tan unificado como lo pintas, Bethel.",
  ui_story_5010_50100801_24_dialog_content = "Cada gremio, cada pandilla... diablos, cada persona tiene sus propios intereses por encima de todo lo demás. Je...",
  ui_story_5010_50100801_25_dialog_content = "Estoy dispuesto a apostar que cada organización está pensando en una forma de salvar la suya en este momento. Algunos incluso pueden optar por ponerse del lado de Rhein, en este punto.",
  ui_story_5010_50100801_26_dialog_content = "Es por eso que eligió atacar personalmente la subasta en este momento. Con la asistencia de todos los jefes principales, podría involucrarlos a todos en el caos.",
  ui_story_5010_50100801_27_dialog_content = "Sin el consentimiento de Lumopolis, Rhein podría realmente...",
  ui_story_5010_50100801_28_dialog_content = "Lamento decepcionarlo, Su Señoría... Pero este es Umbraton.",
  ui_story_5010_50100801_29_dialog_content = "Todos aquí respetan las reglas de Umbraton para su beneficio. Todo el mundo mantiene órdenes por aquí debido al poder de Istvan.",
  ui_story_5010_50100801_30_dialog_content = "En lo que a la mayoría de la gente se refiere, no importa quién actúe como el Señor de las Sombras...",
  ui_story_5010_50100801_31_dialog_content = "Pero Rhein está jugando de esta manera demasiado violenta. Si toma el control de la ciudad, dudo que salga algo bueno.",
  ui_story_5010_50100801_32_dialog_content = "Incluso si Rhein realmente ha derrotado a Istvan, e incluso si conquista todo Umbraton, Lumopolis nunca reconocería...",
  ui_story_5010_50100801_33_dialog_content = "¡Puaj! ¡No sirve de nada hablar de eso ahora! ¡Nuestra principal prioridad es encontrar al Señor de las Sombras!",
  ui_story_5010_50100801_34_dialog_content = "Pero si las palabras de Rhein eran ciertas, Bethel, entonces el Señor de las Sombras...",
  ui_story_5010_50100801_35_dialog_content = "¡Me niego a creer nada de eso, Luke!",
  ui_story_5010_50100801_36_dialog_content = "Incluso si no importa quién actúa como Shadowlord of Umbraton... Pero por ahora, no debe ser Rhein.",
  ui_story_5010_50100801_37_dialog_content = "Estás bien. Más gente va a morir si esto sigue así. Tenemos que detenerlo, no importa lo que quiera.",
  ui_story_5010_50100801_38_dialog_content = "Iré a reunir a los visitantes de Lumopolis y encontraré una manera de solicitar el apoyo de la ciudad.",
  ui_story_5010_50100801_39_dialog_content = "¡Mirar! Esa señal de humo es la que usan nuestros mercenarios en caso de emergencia... Y viene de la dirección del <color=#FFB400>Familia Lin</color>!",
  ui_story_5010_50100801_40_dialog_content = "No tienen muchos luchadores en la ciudad, lo que los convierte en uno de los objetivos más fáciles de atacar.",
  ui_story_5010_50100801_41_dialog_content = "La defensa del centro de la ciudad es sólida. Incluso Rhein estaría en apuros para abrirse paso.",
  ui_story_5010_50100801_42_dialog_content = "¿Eh? ¿El Lin Guild también podría estar bajo ataque?",
  ui_story_5010_50100801_43_dialog_content = "¡Tengo que ir a ayudarlos!",
  ui_story_5010_50100801_44_dialog_content = "Mi trabajo sigue siendo protegerte, PlayerName. Si te vas, me voy.",
  ui_story_5010_50100801_45_dialog_content = "Todos se valen por sí mismos aquí en Umbraton... Me temo que somos los únicos aquí que podemos ayudar a los demás.",
  ui_story_5010_50100801_46_dialog_content = "¡Vamos juntos, entonces!",
  ui_story_5010_50100901_1_dialog_content = "Tú... tú... urgh...",
  ui_story_5010_50100901_2_dialog_content = "Silbido...",
  ui_story_5010_50100901_3_dialog_content = "¿Quién es éste?",
  ui_story_5010_50100901_4_dialog_content = "Este es uno de mis hombres!",
  ui_story_5010_50100901_5_dialog_content = "L... ¿Luke?",
  ui_story_5010_50100901_6_dialog_content = "¿Estás bien, hermano? ¡¿Quien te hizo esto?!",
  ui_story_5010_50100901_7_dialog_content = "Sobreviviré, pero Solus... Ya entraron.",
  ui_story_5010_50100901_8_dialog_content = "Los luchadores más poderosos de la Familia Lin están lejos de la ciudad en este momento... Todo lo que pueden hacer es confiar en la defensa de la ciudad por ahora. no se ve bien...",
  ui_story_5010_50100901_9_dialog_content = "No te preocupes por eso ahora. Solo encuentra un lugar seguro y descansa un poco.",
  ui_story_5010_50100901_10_dialog_content = "...",
  ui_story_5010_50100901_11_dialog_content = "Por dentro... ¡Se han vuelto a llevar los potenciadores!",
  ui_story_5010_50100901_12_dialog_content = "¡Tenemos que darnos prisa!",
  ui_story_5010_50100901_13_dialog_content = "Parece que tendremos que limpiar todo el lugar, ¿eh? Suena divertido.",
  ui_story_5010_50100901_14_dialog_content = "En efecto. no puedo esperar...",
  ui_story_5010_50100901_15_dialog_content = "¡Cadena! ¡Extender!",
  ui_story_5010_50100901_16_dialog_content = "¡Rugido!",
  ui_story_5010_50100902_1_dialog_content = "La lluvia está empezando a caer en serio ahora.",
  ui_story_5010_50100902_2_dialog_content = "Espera a que la familia Lin llegue a casa y vea en qué desastre se ha convertido...",
  ui_story_5010_50100902_3_dialog_content = "Bethel.",
  ui_story_5010_50100902_4_dialog_content = "¿Mmm?",
  ui_story_5010_50100902_5_dialog_content = "Todavía no entiendo... ¿Por qué Blue Lion Guild uniría fuerzas con Solus?",
  ui_story_5010_50100902_6_dialog_content = "No parece que Rhein o Maude realmente puedan ganar algo al unirse.",
  ui_story_5010_50100902_7_dialog_content = "No solo eso, sino que se han enfrentado muchas veces en el pasado. Después de todo, ambos operan principalmente bajo tierra, por lo que compiten constantemente entre sí.",
  ui_story_5010_50100902_8_dialog_content = "Entonces, si es necesario que trabajen juntos... ¿por qué no lo hicieron antes?",
  ui_story_5010_50100902_9_dialog_content = "¿Por qué eligieron esperar hasta hoy para lanzar su golpe...?",
  ui_story_5010_50100902_10_dialog_content = "El itinerario de viaje del Señor de las Sombras. Iba a partir de la ciudad en su aeronave esta mañana...",
  ui_story_5010_50100902_11_dialog_content = "Así como esta peculiar tormenta.",
  ui_story_5010_50100902_12_dialog_content = "Patrones meteorológicos extraños que interrumpen las comunicaciones, así como Eclipses transformados... ¡Ya he visto esto antes!",
  ui_story_5010_50100902_13_dialog_content = "En Dunefire... ¡En Eraveil!",
  ui_story_5010_50100902_14_dialog_content = "Dime, Betel. ¿Qué crees que podría haber motivado a esos dos a arriesgarlo todo de esta manera?",
  ui_story_5010_50100902_15_dialog_content = "No puedo imaginar que destruir la ciudad de esta manera les sirva de alguna manera...",
  ui_story_5010_50100902_16_dialog_content = "¿A menos que fuera para establecer un monopolio sobre el comercio clandestino?",
  ui_story_5010_50100902_17_dialog_content = "Pero el Señor de las Sombras siempre ha hecho la vista gorda ante estas cosas. Nunca ha tomado una postura de línea dura contra ellos.",
  ui_story_5010_50100902_18_dialog_content = "De hecho, muchos productos altamente cuestionables fluyen libremente a través de las sombras.",
  ui_story_5010_50100902_19_dialog_content = "Es por eso...",
  ui_story_5010_50100902_20_dialog_content = "Lo que sea que motive su golpe debe ser aún más atractivo para ellos que un monopolio sobre el comercio clandestino.",
  ui_story_5010_50100902_21_dialog_content = "Pero que puede ser...",
  ui_story_5010_50100902_22_dialog_content = "Lamento interrumpir, Bethel, pero creo que Frankel...",
  ui_story_5010_50100902_23_dialog_content = "Fufufu...",
  ui_story_5010_50100902_24_dialog_content = "¿Qué pasa, Frankel?",
  ui_story_5010_50100902_25_dialog_content = "Boo-foo...",
  ui_story_5010_50100902_26_dialog_content = "¿Qué es eso de allá? Su...",
  ui_story_5010_50100902_27_dialog_content = "¿Mariposas?",
  ui_story_5010_50100902_28_dialog_content = "¿Ah?",
  ui_story_5010_50100902_29_dialog_content = "Hay un puñado de mariposas bajo los aleros...",
  ui_story_5010_50100902_30_dialog_content = "Este no es el momento de observar la naturaleza, Luke.",
  ui_story_5010_50100902_31_dialog_content = "¿Podrías, por favor, alejar tu afán de los insectos y centrarte en rescatar a nuestros compañeros aurorianos?",
  ui_story_5010_50100902_32_dialog_content = "... Algo le pasó a Steelfire Gang.",
  ui_story_5010_50100902_33_dialog_content = "E-Espera, ¿quién es Steelfire Gang? ¿Y cómo sabes que les pasó algo?",
  ui_story_5010_50100902_34_dialog_content = "Este tipo de mariposa es extremadamente sensible a los cambios de temperatura. No debería existir aquí durante esta parte del año.",
  ui_story_5010_50100902_35_dialog_content = "Pero Steelfire Gang tenía un invernadero con algunos de ellos dentro. Hace un tiempo, acepté un trabajo para reparar ese mismo invernadero.",
  ui_story_5010_50100902_36_dialog_content = "Mire hacia los aleros y compruébelo usted mismo.",
  ui_story_5010_50100902_37_dialog_content = "Estas mariposas... Se están refugiando de la lluvia aquí, y se sienten atraídas por nuestro calor corporal.",
  ui_story_5010_50100902_38_dialog_content = "Es muy probable que el invernadero de Steelfire Gang se haya abierto... ¡Debe ser algún tipo de señal!",
  ui_story_5010_50100902_39_dialog_content = "Y una señal que solo tú entenderías, Luke. que raro...",
  ui_story_5010_50100902_40_dialog_content = "¿Qué encontraremos allí, me pregunto?",
  ui_story_5010_50100902_41_dialog_content = "No se sabe... Esta es nuestra única pista, después de todo.",
  ui_story_5010_50100902_42_dialog_content = "De hecho, incluso para ayudar a mantener el orden... No podemos permitirnos quedarnos de brazos cruzados.",
  ui_story_5010_50100902_43_dialog_content = "Gracias a Dios que estabas aquí para ver esto, Luke.",
  ui_story_5010_50100902_44_dialog_content = "No es nada. Sin embargo, me dan pena estas mariposas.",
  ui_story_5010_50100902_45_dialog_content = "A esta temperatura... Sólo tienen media hora antes de morir.",
  ui_story_5010_50100902_46_dialog_content = "La base de Steelfire Gang se encuentra en un terreno bajo, rodeada de barrios marginales.",
  ui_story_5010_50100902_47_dialog_content = "Si fueran atacados, solo puedo imaginar la devastación...",
  ui_story_5010_50100902_48_dialog_content = "No lo averiguaremos quedándonos por aquí. Vamos.",
  ui_story_5010_50101002_1_dialog_content = "Gracias a Dios... Pudimos rescatarlos a todos.",
  ui_story_5010_50101002_2_dialog_content = "Nunca hubiera imaginado que Rhein y Maude también los dejaran intactos.",
  ui_story_5010_50101002_3_dialog_content = "Esto no tiene sentido... Parece que se fueron a toda prisa antes de hacer lo que vinieron a hacer.",
  ui_story_5010_50101002_4_dialog_content = "... Olvídalo, tenemos que atender a los heridos. Afortunadamente, sus heridas son relativamente menores.",
  ui_story_5010_50101002_5_dialog_content = "Dejé una señal para los Mercenarios de la Llama Blanca, deberían estar aquí para brindar apoyo en cualquier momento.",
  ui_story_5010_50101002_6_dialog_content = "¿Cómo conseguiste contactar con ellos?",
  ui_story_5010_50101002_7_dialog_content = "Dejé un rastro de mezclas especiales detrás de nosotros, uno que no desaparece con la lluvia e incluso brilla en la oscuridad.",
  ui_story_5010_50101002_8_dialog_content = "... Debe tener algo que ver con tus insectos, supongo.",
  ui_story_5010_50101002_9_dialog_content = "¡Así es!",
  ui_story_5010_50101002_10_dialog_content = "Espera, qué está pasando aquí...",
  ui_story_5010_50101002_11_dialog_content = "¡Correr! ¡Ve a la cima!",
  ui_story_5010_50101002_12_dialog_content = "¿Adónde se ha escapado Steelfire Gang? ¡Nadie puede salvarnos ahora!",
  ui_story_5010_50101002_13_dialog_content = "¿Dice quién?",
  ui_story_5010_50101002_14_dialog_content = "Este lugar... El aroma de las profundidades del mar impregna este lugar.",
  ui_story_5010_50101002_15_dialog_content = "¡Estos suministros de emergencia son para todos ustedes!",
  ui_story_5010_50101002_16_dialog_content = "¡Balsas, dispositivos de flotación y raciones de emergencia!",
  ui_story_5010_50101002_17_dialog_content = "¡Escuchen!",
  ui_story_5010_50101002_18_dialog_content = "¡No tomes todos los suministros como cachorros hambrientos!",
  ui_story_5010_50101002_19_dialog_content = "¡Es la banda de Istvan! ¡Istvan Gang ha venido a nuestro rescate!",
  ui_story_5010_50101002_20_dialog_content = "¡Gran! ¡Ahora que estás aquí!",
  ui_story_5010_50101002_21_dialog_content = "¿El Señor de las Sombras te ordenó defender este lugar?",
  ui_story_5010_50101002_22_dialog_content = "Dime, ¿está sano y salvo?",
  ui_story_5010_50101002_23_dialog_content = "¿Quién sabe? ¿Pueden las sombras ser lavadas por la lluvia, Bethel?",
  ui_story_5010_50101002_24_dialog_content = "¡Lo estamos arreglando de arriba a abajo, jefe!",
  ui_story_5010_50101002_25_dialog_content = "¿Cuál es la situación en las otras partes de la ciudad?",
  ui_story_5010_50101002_26_dialog_content = "¿Sabemos cuántas víctimas ha habido? ¿Dónde están Solus y los Blue Lions en este momento? ¿Alguno de ustedes ha visto a Maude o Rhein?",
  ui_story_5010_50101002_27_dialog_content = "... Demasiadas preguntas.",
  ui_story_5010_50101002_28_dialog_content = "Todavía no hay muchas bajas, ni idea de dónde están, y no, no las hemos visto.",
  ui_story_5010_50101002_29_dialog_content = "Atender a los heridos es bastante agotador. No mas preguntas.",
  ui_story_5010_50101002_30_dialog_content = "¡Aunque, los gremios que fueron atacados antes están bajo nuestra protección ahora!",
  ui_story_5010_50101002_31_dialog_content = "Los números del enemigo también están empezando a disminuir...",
  ui_story_5010_50101002_32_dialog_content = "Deben haberse asustado por nuestra heroica presencia. Sí, eso tiene que ser.",
  ui_story_5010_50101002_33_dialog_content = "Espera... ¿Me estás diciendo que ya no hay miembros de Solus en la ciudad?",
  ui_story_5010_50101002_34_dialog_content = "Esto no coincide con sus movimientos anteriores...",
  ui_story_5010_50101002_35_dialog_content = "¿Soy solo yo, o el nivel del agua es cada vez más alto aquí?",
  ui_story_5010_50101002_36_dialog_content = "Eso creo... Mis tentáculos no pueden tomar un descanso.",
  ui_story_5010_50101002_37_dialog_content = "El agua... ¡¡Está empezando a fluir aquí!!",
  ui_story_5010_50101002_38_dialog_content = "Los barrios marginales se encuentran en terrenos bajos.",
  ui_story_5010_50101002_39_dialog_content = "Tenemos suerte de que Istvan Gang esté aquí para ayudar...",
  ui_story_5010_50101002_40_dialog_content = "No puedo imaginar el problema en el que estarían estas personas si no fuera por ustedes.",
  ui_story_5010_50101002_41_dialog_content = "¡Oh, no!",
  ui_story_5010_50101002_42_dialog_content = "¡Si la lluvia sigue cayendo así, los barcos y los muelles del Río Dorado estarán en peligro!",
  ui_story_5010_50101002_43_dialog_content = "El agua... los barrios bajos... los muelles y los barcos... Y toda esta lluvia...",
  ui_story_5010_50101002_44_dialog_content = "¡Ay! ¡Así que eso es lo que está pasando! ¡Finalmente entiendo!",
  ui_story_5010_50101002_45_dialog_content = "<size=45><color=#FFB400>¡La presa de las cicatrices!</color></size>",
  ui_story_5010_50101002_46_dialog_content = "¡Ese es su objetivo! ¡Es la presa de las cicatrices!",
  ui_story_5010_50101002_47_dialog_content = "... ¡Lo entiendo!",
  ui_story_5010_50101002_48_dialog_content = "Si la presa se rompiera...",
  ui_story_5010_50101002_49_dialog_content = "Umbraton sufrirá bajas masivas. No solo los barrios marginales serán arrasados por completo, sino que los muelles esenciales de la ciudad también sufrirán graves daños.",
  ui_story_5010_50101002_50_dialog_content = "¡Esto... esto es mucho peor de lo que había imaginado!",
  ui_story_5010_50101002_51_dialog_content = "¿Cómo podemos saber el estado de la presa en este momento?",
  ui_story_5010_50101002_52_dialog_content = "A juzgar por la cantidad de agua aquí, es seguro decir que no ha sido golpeada críticamente.",
  ui_story_5010_50101002_53_dialog_content = "¡Pero tenemos que movernos, y rápido!",
  ui_story_5010_50101101_1_dialog_content = "La presa está justo más adelante. Exploremos el área primero.",
  ui_story_5010_50101101_2_dialog_content = "*Jadeo* ¡Ahí! ¡Es Maude!",
  ui_story_5010_50101101_3_dialog_content = "... ¡La presa ya ha sido perforada!",
  ui_story_5010_50101101_4_dialog_content = "Parece que no aguantará mucho más...",
  ui_story_5010_50101101_5_dialog_content = "¿Viste eso? Están usando armas de fuego.",
  ui_story_5010_50101101_6_dialog_content = "¡Date prisa, antes de que sea demasiado tarde!",
  ui_story_5010_50101101_7_dialog_content = "¡Señor Maude! ¡Señor Rin!",
  ui_story_5010_50101101_8_dialog_content = "¿Vaya? Así que nos encontraron, después de todo.",
  ui_story_5010_50101101_9_dialog_content = "¿También está aquí para presenciar la caída de la presa, Lady Bethel?",
  ui_story_5010_50101101_10_dialog_content = "Pero no te preocupes. Te reunirás con tu amado padre, Lord Istvan, muy pronto.",
  ui_story_5010_50101101_11_dialog_content = "Basta de bromas. ¡Ataque!",
  ui_story_5010_50101101_12_dialog_content = "¡Como si te fuéramos a dejar que te salgas con la tuya!",
  ui_story_5010_50101101_13_dialog_content = "¡Ni en sueños, traidores!",
  ui_story_5010_50101101_14_dialog_content = "Cuídate de estas plagas insignificantes.",
  ui_story_5010_50101101_15_dialog_content = "Tengo algo mucho más importante que hacer. Tomará cada onza de mi concentración...",
  ui_story_5010_50101101_16_dialog_content = "Para preparar esta gran sorpresa para todo Umbraton.",
  ui_story_5010_50101101_17_dialog_content = "¡No dejaré que destruyas la presa!",
  ui_story_5010_50101101_18_dialog_content = "Uwaaa!!",
  ui_story_5010_50101101_19_dialog_content = "¿Realmente debo lidiar con esta escoria del estanque yo mismo...?",
  ui_story_5010_50101101_20_dialog_content = "Supongo que debo calentar primero...",
  ui_story_5010_50101101_21_dialog_content = "¡Disfrutando el sabor de tu última lucha sin sentido!",
  ui_story_5010_50101101_22_dialog_content = "Ustedes dos parecen estar de muy buen humor.",
  ui_story_5010_50101101_23_dialog_content = "<size=45>¡¿T... tú...?!</size>",
  ui_story_5010_50101101_24_dialog_content = "<size=45>Cómo... ¡¿Cómo sigues vivo?!</size>",
  ui_story_5010_50101101_25_dialog_content = "¡Deberías haber volado en pedazos!",
  ui_story_5010_50101101_26_dialog_content = "Maude... debo decir que tu forma de dar la bienvenida a un nuevo huésped carece de decoro.",
  ui_story_5010_50101101_27_dialog_content = "Destruir mi aeronave solo me dio algunos rasguños, nada más...",
  ui_story_5010_50101101_28_dialog_content = "Que me presente ante ustedes ahora... es un testimonio del completo y absoluto fracaso de sus esfuerzos.",
  ui_story_5010_50101101_29_dialog_content = "Todos los miembros de Solus responsables de la lucha en la ciudad han sido detenidos, así como sus cómplices.",
  ui_story_5010_50101101_30_dialog_content = "Jajaja... Debo admitir que esos monstruos transformadores fueron bastante desafiantes, pero...",
  ui_story_5010_50101101_31_dialog_content = "Solus ya no existe, y el Blue Lion Guild compartirá el mismo destino.",
  ui_story_5010_50101101_32_dialog_content = "Tus activos se distribuirán equitativamente entre el resto de Umbraton, como compensación por los problemas que has causado. En nombre de los líderes de la ciudad... ¡Me gustaría ofrecer mi más sincero agradecimiento por su generosa donación! Jajajajaja!",
  ui_story_5010_50101101_33_dialog_content = "¿Crees que puedes detenernos con tus palabras sin sentido?",
  ui_story_5010_50101101_34_dialog_content = "Me temo que está diciendo la verdad. Mira las señales de humo saliendo de la ciudad...",
  ui_story_5010_50101101_35_dialog_content = "Parece que debemos cambiar de estrategia, Maude...",
  ui_story_5010_50101101_36_dialog_content = "Este es el final de la línea para ti, Rhein.",
  ui_story_5010_50101101_37_dialog_content = "En cuanto a mí... ¡Yo, y solo yo, soy más que suficiente!",
  ui_story_5010_50101101_38_dialog_content = "¡¡¡Haré de este lugar el lugar de descanso final para cada persona aquí!!!",
  ui_story_5010_50101101_39_dialog_content = "Poder... Poder infinito... ¡¡¡Es mío!!!",
  ui_story_5010_50101101_40_dialog_content = "Aquí viene... ¡Maude se va a tomar esas pastillas!",
  ui_story_5010_50101101_41_dialog_content = "H-Él lo hizo... Maude se los comió a todos... ¡Se ve completamente diferente de los otros que se los llevaron!",
  ui_story_5010_50101101_42_dialog_content = "¡¿Qué es esta intensa presión?!",
  ui_story_5010_50101101_43_dialog_content = "<anim type=Shake><size=45>Graaaaaaaaaagh!!!</size></anim>",
  ui_story_5010_50101101_44_dialog_content = "<anim type=Shake><size=45>Poder...</size></anim>",
  ui_story_5010_50101101_45_dialog_content = "¡Todos juntos! ¡Ataque!",
  ui_story_5010_50101101_46_dialog_content = "Padre, todavía estás herido. Luchemos contra Maude. ¡Haz lo que puedas para proteger la presa!",
  ui_story_5010_50101101_47_dialog_content = "¡A tu izquierda, Luke!",
  ui_story_5010_50101101_48_dialog_content = "¡Cuidado, está a punto de atacar!",
  ui_story_5010_50101101_49_dialog_content = "Por fin... Por fin ha llegado el momento.",
  ui_story_5010_50101101_50_dialog_content = "¡¡¡Escuchen mis órdenes, todos!!!",
  ui_story_5010_50101201_1_dialog_content = "Llegas tarde, PlayerName. ¡El Señor de las Sombras te ha estado esperando todo este tiempo!",
  ui_story_5010_50101201_2_dialog_content = "¡Vaya! R-¿En serio? Corrí lo más rápido que pude...",
  ui_story_5010_50101201_3_dialog_content = "Aunque supongo que con ganancias tan escasas como esta, tu tardanza puede ser excusada.",
  ui_story_5010_50101201_4_dialog_content = "¿Te mataría decir la verdad, por una vez? Tus tentáculos no se caerán si lo haces, ¿sabes?",
  ui_story_5010_50101201_5_dialog_content = "Ah... ¡Sabía que no llegaba tarde!",
  ui_story_5010_50101201_6_dialog_content = "¡Ay...! ¡E-Espera, quédate atrás! ¡Todavía tengo otras cosas de las que ocuparme!",
  ui_story_5010_50101201_7_dialog_content = "Estos son los documentos de transferencia de propiedad de todos los activos de Caelestite, PlayerName. Requerirán su firma.",
  ui_story_5010_50101201_8_dialog_content = "Además, según las instrucciones del Señor de las Sombras... Nos gustaría ofrecerle la <color=#FFB400>componentes de la sala de simulación</color> de la subasta, de forma gratuita, como muestra de nuestra gratitud.",
  ui_story_5010_50101201_9_dialog_content = "Luke, de los Mercenarios de la Llama Blanca, acordó entregar dichas partes a Eraveil en un futuro cercano.",
  ui_story_5010_50101201_10_dialog_content = "Lucas! ¡Tú también estás aquí!",
  ui_story_5010_50101201_11_dialog_content = "Nos encontramos de nuevo, ustedes dos.",
  ui_story_5010_50101201_12_dialog_content = "Mis disculpas por interrumpir su sentida reunión.",
  ui_story_5010_50101201_13_dialog_content = "pittman? ¿Ya concluyó el juicio?",
  ui_story_5010_50101201_14_dialog_content = "No del todo... He venido a despedirme. Mis órdenes son escoltar a Rhein de regreso a Lumopolis para continuar con su juicio.",
  ui_story_5010_50101201_15_dialog_content = "Es un milagro que haya logrado sobrevivir en primer lugar...",
  ui_story_5010_50101201_16_dialog_content = "Esperar. Rhein es ciudadano de Umbraton. ¿Qué derecho tienes para llevarlo de regreso a Lumopolis?",
  ui_story_5010_50101201_17_dialog_content = "Lo siento... Pero estas órdenes vienen de alguien muy por encima de mí.",
  ui_story_5010_50101201_18_dialog_content = "No podría negarme, incluso si quisiera hacerlo.",
  ui_story_5010_50101201_19_dialog_content = "Pero...",
  ui_story_5010_50101201_20_dialog_content = "Podría añadir... Que el mismísimo Señor de las Sombras también ha aprobado estas órdenes.",
  ui_story_5010_50101201_21_dialog_content = "En efecto. Te deseo la mejor de las suertes, Pittman.",
  ui_story_5010_50101201_22_dialog_content = "Te agradezco una vez más tu comprensión... Shadowlord.",
  ui_story_5010_50101201_23_dialog_content = "PlayerName, Luke, Lady Bethel... Hasta el próximo encuentro.",
  ui_story_5010_50101201_24_dialog_content = "... Padre.",
  ui_story_5010_50101201_25_dialog_content = "Señor de la sombra.",
  ui_story_5010_50101201_26_dialog_content = "Hmm... El estado de ánimo parece haber mejorado un poco.",
  ui_story_5010_50101201_27_dialog_content = "Ah, pero por supuesto... Después de todo, el tiempo ha mejorado.",
  ui_story_5010_50101201_28_dialog_content = "Istvan!",
  ui_story_5010_50101201_29_dialog_content = "Hola, PlayerName.",
  ui_story_5010_50101201_30_dialog_content = "Permítanme expresar mis más profundas disculpas. Fuiste arrastrado a los asuntos problemáticos de nuestra ciudad, y no en pequeña medida.",
  ui_story_5010_50101201_31_dialog_content = "¿E-Eh? No fue nada, de verdad... ¡No hay necesidad de disculparse!",
  ui_story_5010_50101201_32_dialog_content = "Padre... ¿Puede el destino de Rhein ser tan fácil...",
  ui_story_5010_50101201_33_dialog_content = "Lo entenderás muy pronto, querida.",
  ui_story_5010_50101201_34_dialog_content = "¿E-Entender qué?",
  ui_story_5010_50101201_35_dialog_content = "Puedo entender permitir que nuestros adversarios expongan su conspiración ellos mismos, para que podamos recoger los pedazos después...",
  ui_story_5010_50101201_36_dialog_content = "¿Pero no deberíamos ser nosotros los que castiguen a Rhein por sus crímenes?",
  ui_story_5010_50101201_37_dialog_content = "¿Eh? ¿Llamas estrategia a dejar que las cosas se salgan de control?",
  ui_story_5010_50101201_38_dialog_content = "Al permitir que Rhein muestre todas sus cartas, evitamos darle la oportunidad de seguir tramando en las sombras y evitar que él y sus secuaces causen más problemas en el futuro.",
  ui_story_5010_50101201_39_dialog_content = "Pero si no hubiéramos tenido la situación bajo control al final... ¿No habrían muerto innumerables personas a causa de eso?",
  ui_story_5010_50101201_40_dialog_content = "Las personas con corazones puros e ingenuos no pueden sobrevivir aquí en Umbraton... Especialmente no en una posición de poder.",
  ui_story_5010_50101201_41_dialog_content = "¿Quizás fue una prueba para Bethel? Después de todo, estoy seguro de que Lord Istvan ha pensado mucho en quién lo sucederá en el futuro...",
  ui_story_5010_50101201_42_dialog_content = "Basta de eso. En cualquier caso, existe la posibilidad de que le den una sentencia más leve en Lumopolis, mucho menos de lo que se merece.",
  ui_story_5010_50101201_43_dialog_content = "No es solo una posibilidad. Sinceramente, me sorprendería que no aligeraran su sentencia.",
  ui_story_5010_50101201_44_dialog_content = "¿Ah?",
  ui_story_5010_50101201_45_dialog_content = "Si quisieran ejecutar o castigar severamente a un criminal, Umbraton es el lugar para hacerlo. Entonces, ¿por qué tendrían que llevarlo de regreso a Lumopolis?",
  ui_story_5010_50101201_46_dialog_content = "No importa cuán fuerte fuera Rhein, si no tuviera algún tipo de ayuda tras bambalinas de Lumopolis...",
  ui_story_5010_50101201_47_dialog_content = "Incluso si lograra derrotarnos, no habría podido actuar como Shadowlord por mucho tiempo.",
  ui_story_5010_50101201_48_dialog_content = "Si esos jugadores ocultos aún no quieren que Rhein muera, estoy seguro de que no dejarán que lo ejecuten.",
  ui_story_5010_50101201_49_dialog_content = "¿Tengo razón, Su Señoría?",
  ui_story_5010_50101201_50_dialog_content = "Entiendo sus palabras, pero este es un tema que preferiría evitar discutir.",
  ui_story_5010_50101201_51_dialog_content = "Lady Bethel, puedo asegurarle que la decisión de Lord Istvan es una en la que ha pensado mucho. Por favor, no te enojes tanto por eso.",
  ui_story_5010_50101201_52_dialog_content = "Es probablemente la persona más racional que ha estado en esta posición durante tanto tiempo.",
  ui_story_5010_50101201_53_dialog_content = "Puedo entenderlo, pero todavía me niego a aceptarlo.",
  ui_story_5010_50101201_54_dialog_content = "Ya sea Lumopolis o Umbraton... sus esquemas se profundizan cada día.",
  ui_story_5010_50101201_55_dialog_content = "Una cosa más, PlayerName. Mi investigación sobre los potenciadores aún está en curso. Estoy seguro de que necesitaré su ayuda en el futuro.",
  ui_story_5010_50101201_56_dialog_content = "¿No es eso obvio? La gente está cooperando con Eclipse, y...",
  ui_story_5010_50101201_57_dialog_content = "Debo pedirle que se abstenga de hacer afirmaciones sin fundamento antes de que obtengamos las pruebas adecuadas. Encontrar la verdad requerirá no poca paciencia.",
  ui_story_5010_50101201_58_dialog_content = "*Suspira* Bien.",
  ui_story_5010_50101201_59_dialog_content = "Seguiré rastreando a los aliados restantes de Rhein en Umbraton. Atraparemos hasta el último de esos sinvergüenzas.",
  ui_story_5010_50101201_60_dialog_content = "El costo de la rebelión fue demasiado grave. No podemos permitir que vuelva a suceder.",
  ui_story_5010_50101201_61_dialog_content = "Bethel, Rhein no fue la primera persona en desafiar a Istvan, ni será la última.",
  ui_story_5010_50101201_62_dialog_content = "A juzgar por este resultado, Istvan es lo suficientemente fuerte como para manejar la situación, por lo que todos deberían continuar manteniendo el orden aquí.",
  ui_story_5010_50101201_63_dialog_content = "Todos los escuadrones, bandas y gremios de mercenarios...",
  ui_story_5010_50101201_64_dialog_content = "Ah, gremios... Por cierto, Luke, ¿cuál es la situación con la familia Lin?",
  ui_story_5010_50101201_65_dialog_content = "Ya he consultado. Los miembros principales de la familia Lin están excavando una reliquia misteriosa y no volverán pronto.",
  ui_story_5010_50101201_66_dialog_content = "Ya veo. Tendré que agradecer a la familia Lin cuando tenga la oportunidad.",
  ui_story_5010_50101201_67_dialog_content = "Te avisaremos tan pronto como sepamos algo.",
  ui_story_5010_50101201_68_dialog_content = "Bueno, es hora de despedirnos de todos ustedes.",
  ui_story_5010_50101201_69_dialog_content = "Estimado Naroxel:",
  ui_story_5010_50101201_70_dialog_content = "\"Entonces, eso resume nuestro viaje a Umbraton... Aunque tengo algunos remordimientos...\"",
  ui_story_5010_50101201_71_dialog_content = "\"Todavía me alegro de haber recibido los componentes de la sala de simulación...\"",
  ui_story_5010_50101201_72_dialog_content = "\"Aún se desconoce su uso específico. Me he puesto en contacto con varios expertos científicos y tecnológicos...\"",
  ui_story_5010_50101201_73_dialog_content = "\"Gracias de nuevo, Naroxel. Y que la naturaleza te cuide\".",
  ui_story_5010_50101201_74_dialog_content = "\"De tu amigo, PlayerName.\""
}
return config
